UPDATE roadmap_features SET title='Authentication',description='A selected server profile supplies the account endpoint and protocol version; accepted credentials advance the connection to the server''s next login stage, while denial, timeout, or socket loss leaves no authenticated session.',acceptance_criteria_json='["Against an authorized protocol fixture, accepted and rejected replies must produce the expected connection states; a timeout/close case must clear pending authentication. Preserve the sanitized packet/state trace as integration evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='networking.authentication' AND category_id='networking' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Server selection',description='The configured server list exposes only usable entries with their login address, protocol type, and required account settings; selecting one binds subsequent login packets to that exact profile.',acceptance_criteria_json='["A fixture with two server profiles must select the requested endpoint and packet parser; an unknown or incomplete profile must fail before a socket is opened. Record profile fixture and connection-selection assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm"]',updated_at=unixepoch() WHERE id='networking.server-selection' AND category_id='networking' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Character selection',description='After successful account login, the client presents only characters returned for that account and sends the chosen slot to the character server; a stale or invalid slot cannot enter a map session.',acceptance_criteria_json='["A sanitized character-list fixture must preserve slot identity and select the requested character; an out-of-range slot or rejected reply must keep map-server entry disabled. Capture the decoded response and state assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='networking.character-selection' AND category_id='networking' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Map server connection',description='A valid character-server transfer response supplies the map endpoint and session credentials used to open the map connection; rejected or incomplete transfer data must not create an in-game state.',acceptance_criteria_json='["A local protocol server fixture must validate the transfer fields and observe the map handshake; malformed address, denial, and timeout must return a connection error with no synchronized world. Keep the transcript as integration evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='networking.map-server-connection' AND category_id='networking' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Packet framing',description='The byte stream tokenizer emits complete packets according to the selected server''s packet-length table, including packets split across reads and several packets coalesced in one read.',acceptance_criteria_json='["Deterministic byte-stream tests must prove split/coalesced frames produce the exact ordered packet boundaries and that unknown length or truncated input is rejected without consuming later valid bytes. Keep fixture bytes and boundary assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/MessageTokenizer.pm"]',updated_at=unixepoch() WHERE id='networking.packet-framing' AND category_id='networking' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Packet interpretation',description='A packet selected by the active protocol table is decoded into the documented typed event and field values; unknown opcodes or truncated payloads are surfaced without applying a partial world update.',acceptance_criteria_json='["Golden packet fixtures must assert opcode-to-event mapping and decoded fields for each supported protocol profile; malformed and unknown packets must return explicit errors and preserve prior state. Store fixture provenance and decoder assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/PacketParser.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='networking.packet-interpretation' AND category_id='networking' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Session synchronization',description='Login, character, and map transitions update one coherent session state only after corresponding server responses; duplicate or late packets cannot move a closed session backward or mark an incomplete session active.',acceptance_criteria_json='["A scripted packet sequence must assert the allowed state transition after each reply and ignore/reject stale sequence events; disconnect between stages must leave no authenticated character or map state. Retain ordered event trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='networking.session-synchronization' AND category_id='networking' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Automatic reconnection',description='When an established connection is lost and retry is enabled, the client retries the configured endpoint under the configured retry policy and resumes only after a fresh server handshake.',acceptance_criteria_json='["A deterministic clock/socket fixture must assert retry scheduling, bounded attempts/backoff, and a successful reconnect path; disabling retry or exhausting attempts must expose a disconnected state without duplicate sessions. Save event and timer assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='networking.automatic-reconnection' AND category_id='networking' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Relog',description='The relog command closes the current session and starts the configured login sequence again after its requested delay; it does not reuse a stale map or character session token.',acceptance_criteria_json='["Command tests with a fake clock must assert close-before-login ordering and the selected delay; cancellation or failed login must remain disconnected and report the failure. Record command input and emitted state events."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='networking.relog' AND category_id='networking' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Disconnection handling',description='A socket close, server disconnect packet, or protocol timeout terminates the affected connection and reports the reason while clearing only state owned by that connection.',acceptance_criteria_json='["Integration fixtures for each disconnect cause must assert one terminal event, released socket/task resources, and no false in-game status; repeated close notifications must not duplicate recovery actions. Keep sanitized traces."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='networking.disconnection-handling' AND category_id='networking' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Session recovery',description='After a recoverable disconnect, the client reconstructs login progress from fresh server responses rather than restoring stale transient tokens or character coordinates.',acceptance_criteria_json='["A deterministic staged-session test must interrupt at account, character, and map stages and assert recovery resumes from the first valid stage; unrecoverable authentication errors must stop retry and explain the failure. Preserve state-machine test output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='networking.session-recovery' AND category_id='networking' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Character creation',description='Character creation sends the requested appearance and slot fields to a server profile that supports creation and reports the server''s accepted character record; validation failure does not select a nonexistent character.',acceptance_criteria_json='["Against an authorized test server, submit valid and invalid creation requests and assert the returned slot/identity or rejection; no local character is added before server confirmation. Keep sanitized request/response evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='networking.character-creation' AND category_id='networking' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='PIN',description='When the selected server requires a PIN, the client sends the PIN challenge response using that profile''s supported exchange and proceeds only on server acceptance.',acceptance_criteria_json='["A protocol fixture must exercise accepted PIN, rejected PIN, and timeout responses; only acceptance may continue authentication, and the PIN must not appear in logs or persisted diagnostics. Retain redacted integration trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='networking.pin' AND category_id='networking' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='OTP',description='For a server profile that requests a one-time code, the client prompts or obtains the configured OTP input and sends it in the corresponding authentication stage; rejection or expiry returns to an unauthenticated state.',acceptance_criteria_json='["An authorized protocol fixture must exercise OTP challenge, valid response, invalid response, and expired response; assert stage ordering and that secrets are redacted. Store the sanitized exchange trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/otp/otp.pl"]',updated_at=unixepoch() WHERE id='networking.otp' AND category_id='networking' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Server transitions',description='When the server directs the character between supported server endpoints, the client closes the previous transport and establishes the newly advertised endpoint with the supplied session context.',acceptance_criteria_json='["A two-endpoint protocol fixture must assert close/open ordering and preserve character identity only after acceptance; invalid transfer data or denial must not leave both transports active. Keep transition trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='networking.server-transitions' AND category_id='networking' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Multiple protocol versions',description='Each declared protocol profile selects its own packet identifiers, lengths, and encodings; a packet valid in one profile is not silently decoded with another profile''s rules.',acceptance_criteria_json='["For every claimed version, golden fixtures must decode to the same semantic event where applicable and reject a cross-version mismatch; store the profile-to-fixture matrix and test output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/PacketParser.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='networking.multiple-protocol-versions' AND category_id='networking' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Server profiles',description='A named profile supplies a complete, validated set of endpoint, protocol, and region settings and is selected as one unit for connection and decoding.',acceptance_criteria_json='["Profile parsing tests must load two distinct profiles and assert endpoint/parser selection; missing required values and duplicate names must be reported before network startup. Preserve redacted profile fixtures."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm"]',updated_at=unixepoch() WHERE id='networking.server-profiles' AND category_id='networking' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Authorized proxy modes',description='A proxy mode is enabled only when the operator explicitly configures the supported local forwarding endpoint; it forwards permitted client traffic while preserving packet boundaries and reports upstream loss.',acceptance_criteria_json='["A loopback client/server integration test must verify bidirectional byte preservation and disconnect propagation; invalid bind targets or disabled proxy mode must not open a listener. Keep a local trace and configuration fixture."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/XKore.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/XKoreProxy.pm"]',updated_at=unixepoch() WHERE id='networking.authorized-proxy-modes' AND category_id='networking' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Position',description='The character''s position is the last coordinate confirmed by a server movement or map-state event, not the most recently requested destination; map changes reset coordinates to the new field context.',acceptance_criteria_json='["Feed movement request, acknowledgment, rejection, and map-change fixtures into the state reducer; assert only confirmed coordinates become current and old-map positions are discarded. Keep the deterministic event sequence and resulting state."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.position' AND category_id='world' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='HP/SP',description='Character HP and SP reflect the latest server values and remain within the protocol''s reported maxima; missing or stale updates do not fabricate recovery.',acceptance_criteria_json='["Apply full, partial, duplicate, and out-of-order status fixtures and assert current/max values and update ordering; invalid ranges are rejected without replacing the last valid status. Preserve table-driven state assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.hp-sp' AND category_id='world' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Character identification',description='The session binds server-provided character identity and slot metadata to the active character and clears that identity when the session ends.',acceptance_criteria_json='["A login fixture must assert the selected server identity fields match the active character; a failed selection or disconnect must clear the binding. Save sanitized packet fixture and state snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.character-identification' AND category_id='world' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Actors',description='Entity updates create, update, and remove actors by stable server identity while keeping actor type and map membership consistent.',acceptance_criteria_json='["A deterministic spawn/update/remove stream must leave one actor per server ID with the final fields; duplicate spawns and removal of unknown IDs must not corrupt the list. Keep event sequence and snapshot evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ActorList.pm"]',updated_at=unixepoch() WHERE id='world.actors' AND category_id='world' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Monsters',description='Monster actor records expose server-reported identity, position, movement, and status needed by targeting and visibility logic; disappearance removes stale entries.',acceptance_criteria_json='["Monster spawn/move/status/disappear fixtures must update the corresponding record and remove it on the server''s disappearance event; malformed updates must leave the last valid record intact. Preserve decoded fixture assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Monster.pm"]',updated_at=unixepoch() WHERE id='world.monsters' AND category_id='world' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Players',description='Player actor records distinguish other characters from the local character and update name, position, and visible status from server events.',acceptance_criteria_json='["A fixture containing local and remote IDs must not overwrite the local record; remote updates and removal must affect only that player. Keep actor-map test output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Player.pm"]',updated_at=unixepoch() WHERE id='world.players' AND category_id='world' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='NPCs',description='NPC actor records retain server identity, class/name when available, and position, and are removed when the server removes them.',acceptance_criteria_json='["NPC spawn, name-resolution, movement, and removal fixtures must produce the expected map index; incomplete name data remains explicitly unknown rather than guessed. Preserve fixture and assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/NPC.pm"]',updated_at=unixepoch() WHERE id='world.npcs' AND category_id='world' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Portals',description='Portal entities map a server-reported source/destination pair to a traversable transition only when both endpoints are known; stale or partial records are not treated as routes.',acceptance_criteria_json='["A field/portal fixture with valid, missing, and removed endpoints must build only the valid transition and delete it after removal; keep parsed fixture and route graph assertion."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Portal.pm"]',updated_at=unixepoch() WHERE id='world.portals' AND category_id='world' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Attributes',description='Attribute updates store each reported base/job attribute separately and apply only server-confirmed values; unknown attribute identifiers are rejected or retained as unknown.',acceptance_criteria_json='["Table-driven attribute packets must update only the named field and leave other attributes unchanged; unknown IDs and truncated values must produce explicit decode errors. Keep golden packet results."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.attributes' AND category_id='world' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Experience',description='Base and job experience gains update their separate counters from server values without double-applying duplicate packets.',acceptance_criteria_json='["A deterministic sequence of initial status and gain packets must yield exact base/job totals; duplicate or stale events must not increment totals twice. Preserve event stream and expected counters."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.experience' AND category_id='world' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Levels',description='A level-up event changes the relevant base or job level only after server confirmation and does not infer a level from experience alone.',acceptance_criteria_json='["Status/level-up fixtures must assert the correct level and associated points update; a gain below the threshold or duplicate notification must not create a second level. Keep packet fixture and state diff."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.levels' AND category_id='world' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Negative status effects',description='Negative status effects track server-reported start, refresh, and end events with their identifiers and duration when supplied; expired or removed effects are not shown as active.',acceptance_criteria_json='["Deterministic status event tests must cover apply, refresh, expiry, explicit removal, and unknown status IDs; only active known effects appear in snapshots. Preserve clock-controlled assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.negative-status-effects' AND category_id='world' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Damage',description='Damage events attribute source, target, amount, and damage type only from decoded server evidence; malformed or duplicate events cannot alter HP twice.',acceptance_criteria_json='["A packet fixture must yield the expected combat event and independently reconcile HP status; duplicate display events must not reapply damage. Keep raw fixture, decoded event, and state comparison."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.damage' AND category_id='world' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Death',description='A death notification marks the character unavailable for actions and records the server-confirmed death state without assuming respawn or restoring HP.',acceptance_criteria_json='["A state-machine test must assert combat/movement actions are gated on death and remain gated until a respawn/status response; duplicate death events are idempotent. Preserve transitions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.death' AND category_id='world' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Respawn',description='A respawn event clears the dead state and adopts the server-confirmed map and position; a requested respawn action alone does not move the character in local state.',acceptance_criteria_json='["A deterministic event sequence must remain dead until server confirmation, then set the returned coordinates; rejection, timeout, or map mismatch leaves recovery pending/error rather than falsely alive. Retain event trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.respawn' AND category_id='world' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Automatic attribute distribution',description='Configured attribute targets consume available stat points in the configured order and stop when targets are met or the server reports no points remain.',acceptance_criteria_json='["A pure allocator fixture must produce the exact ordered requests for multiple target profiles; insufficient points, invalid target, or rejected server response must not be recorded as allocated. Keep allocation and response assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.automatic-attribute-distribution' AND category_id='world' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Automatic skill point distribution',description='Configured skill priorities spend only currently available job points on eligible skills and obey each skill''s prerequisites and maximum level.',acceptance_criteria_json='["A deterministic skill-tree fixture must assert the chosen skill order and resulting levels; unmet prerequisite, insufficient points, or server rejection must stop subsequent requests. Save fixture and request sequence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.automatic-skill-point-distribution' AND category_id='world' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Special states',description='Special states are represented only from recognized server status events, including start, update, and end, without inferring effects from unrelated actor fields.',acceptance_criteria_json='["A table-driven event fixture must assert recognized state transitions and ignore/reject unknown state IDs; end/disconnect clears applicable transient state. Preserve state snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.special-states' AND category_id='world' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Map properties',description='Loaded field metadata exposes only declared map flags such as restrictions or movement properties and applies them to route/command validation.',acceptance_criteria_json='["A field fixture with known flags must yield those exact properties and block a prohibited test action; absent or malformed metadata remains unknown and is not treated as permissive proof. Keep field file and validation output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.map-properties' AND category_id='world' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Reputation',description='Reputation values are displayed only when a supported server packet supplies them and are scoped to the correct character or entity.',acceptance_criteria_json='["A server fixture must associate a reputation update with its source identity; unsupported profiles and unknown identifiers must expose unavailable data instead of synthesized values. Retain packet mapping evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.reputation' AND category_id='world' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Achievements',description='Achievement entries and completion state are taken from server-provided achievement data; unsupported achievement packets do not create local completion records.',acceptance_criteria_json='["A protocol fixture must map a supported achievement response to the reported ID/progress/status and ignore duplicate completion; unsupported-profile tests must remain explicitly unavailable. Keep fixture and decoder assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='world.achievements' AND category_id='world' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Map field loading',description='The field loader resolves the selected map''s supported field file, dimensions, and cell data into a bounded grid; missing or malformed fields fail with a named load error rather than an empty walkable map.',acceptance_criteria_json='["Use a small versioned field fixture with known dimensions and blocked cells; assert exact coordinates and a clear missing/truncated-file error. Preserve fixture hash and parser output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/FileParsers.pm"]',updated_at=unixepoch() WHERE id='navigation.map-field-loading' AND category_id='navigation' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Walkability',description='A cell is traversable only when the selected field data marks it walkable and it satisfies the movement rules; out-of-bounds cells are never considered valid.',acceptance_criteria_json='["A deterministic grid fixture must assert walkable, blocked, and out-of-bounds results, including boundaries; keep the fixture and truth-table test output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.walkability' AND category_id='navigation' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Pathfinding',description='Given a start and reachable goal on a field grid, routing returns a legal path through walkable cells; unreachable goals return an explicit no-route result.',acceptance_criteria_json='["Deterministic maps with corridors, obstacles, and disconnected regions must assert path endpoints and every adjacent transition; the disconnected case must return no route. Preserve map fixtures and path assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.pathfinding' AND category_id='navigation' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Movement',description='A requested step is sent only when it is legal for the active field and movement constraints; current position remains the last server-confirmed location until acknowledgment.',acceptance_criteria_json='["With a fake transport and movement packet fixture, assert the encoded target and that position changes only after acknowledgment; rejection, timeout, or map change cancels the pending step. Keep packet/state trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.movement' AND category_id='navigation' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Arrival confirmation',description='A task reports arrival only after server evidence places the character at the requested destination or within the explicitly configured tolerance; requesting movement is not arrival.',acceptance_criteria_json='["A fake-clock movement test must remain pending after command send and complete only on qualifying position confirmation; rejected, interrupted, or wrong-map updates must not emit arrival. Preserve event assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.arrival-confirmation' AND category_id='navigation' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Dynamic obstacles',description='Newly observed blocking actors or field changes invalidate path segments that now collide with movement constraints and cause a safe replan.',acceptance_criteria_json='["A map fixture changes one cell from walkable to blocked during traversal; assert the replacement path avoids it and no step is issued into the blocked cell. Save before/after route outputs."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.dynamic-obstacles' AND category_id='navigation' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Random walk',description='When no explicit destination is active, randomWalk chooses a reachable walkable destination within configured bounds using the injected random source.',acceptance_criteria_json='["A seeded field fixture must produce repeatable valid destinations and each path must remain on walkable cells; an empty reachable area must return no destination without looping. Keep seed and result set."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.random-walk' AND category_id='navigation' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Stuck character recovery',description='Lack of confirmed position progress across the configured observation window triggers a recovery action, while ordinary latency or an in-progress step does not.',acceptance_criteria_json='["A fake clock and movement acknowledgments must distinguish progress from a stuck timeout; assert the configured recovery path and a bounded stop when recovery also fails. Preserve event timeline."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.stuck-character-recovery' AND category_id='navigation' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Lock map',description='A configured lockMap constrains route destinations and ongoing movement to the designated field; leaving it requires an explicit supported transition or is rejected.',acceptance_criteria_json='["Route fixtures must allow destinations inside the lock map and reject outside goals; a server-confirmed map change outside it must raise a policy event and stop autonomous travel. Keep config and route assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.lock-map' AND category_id='navigation' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Route recalculation',description='When a route edge becomes invalid or the goal changes, the route task computes a new path from the confirmed current position without replaying completed steps.',acceptance_criteria_json='["A deterministic event sequence modifies an obstacle and moves the goal; assert the next step starts from latest confirmed location and excludes completed segments. Preserve old/new route fixtures."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.route-recalculation' AND category_id='navigation' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Inter-map routes',description='The route planner composes known field paths and verified portal transitions to reach a target map, reporting missing or disconnected map links explicitly.',acceptance_criteria_json='["A small multi-map graph fixture must choose a valid sequence of maps/portals and return no inter-map route when disconnected; keep graph fixture and selected transition list."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/CalcMapRoute.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/MapRoute.pm"]',updated_at=unixepoch() WHERE id='navigation.inter-map-routes' AND category_id='navigation' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Portals',description='A portal traversal is offered only when the current map/coordinate matches a known portal entrance and its destination is valid; arrival on the destination map is confirmed by server state.',acceptance_criteria_json='["A two-field fixture must choose the matching entrance and await destination-map confirmation; missing destination or failed transition must not advance the route. Preserve portal fixture and transition events."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/CalcMapRoute.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Portal.pm"]',updated_at=unixepoch() WHERE id='navigation.portals' AND category_id='navigation' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='NPC transport',description='A scheduled NPC transport is used only when its NPC, interaction steps, and destination are defined for the selected server profile.',acceptance_criteria_json='["An authorized-server integration fixture must exercise the expected dialogue and destination response; missing schedule, menu mismatch, or NPC timeout must abort the route and report the failed step. Keep sanitized dialogue trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/CalcMapRoute.pm"]',updated_at=unixepoch() WHERE id='navigation.npc-transport' AND category_id='navigation' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Teleport',description='Teleport actions consume only an explicitly available supported item or server-approved skill and complete only after a server-confirmed position change.',acceptance_criteria_json='["A fake inventory plus authorized protocol fixture must validate resource selection and position confirmation; no-resource, cooldown, denial, and timeout cases must not report success. Keep request/reply evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Teleport.pm"]',updated_at=unixepoch() WHERE id='navigation.teleport' AND category_id='navigation' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Save map',description='saveMap establishes a travel destination only from a map and coordinate confirmed by the server and applies the configured return policy.',acceptance_criteria_json='["A command/config test must store the confirmed map/coordinates and route home accordingly; missing destination and failed save must leave prior setting unchanged. Preserve config fixture and route output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.save-map' AND category_id='navigation' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Warp Portal',description='Warp Portal is offered as a transition only when the skill is available, target memo/coordinate is valid, and the server confirms creation or use of the portal.',acceptance_criteria_json='["A skill-state fixture and authorized server test must distinguish cast request from confirmed portal transition; missing skill, invalid target, interruption, or denial leaves route unchanged. Keep sanitized event evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/CalcMapRoute.pm"]',updated_at=unixepoch() WHERE id='navigation.warp-portal' AND category_id='navigation' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Memos',description='A memo destination is selectable only from locations confirmed and retained by the supported server behavior; unconfirmed memo slots are unavailable.',acceptance_criteria_json='["An authorized protocol fixture must round-trip supported memo slots and reject an empty/unknown slot; the selected target must not be substituted when the server declines it. Retain sanitized reply fixture."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Teleport.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='navigation.memos' AND category_id='navigation' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Transport items',description='A travel item is used only if it exists in inventory, is allowed by map restrictions, and targets a known destination supported by server data.',acceptance_criteria_json='["A deterministic inventory/map fixture must select an eligible item and await confirmed map change; absent item, prohibited map, unknown destination, and server rejection must be explicit failures. Keep choice and transition assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Teleport.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt"]',updated_at=unixepoch() WHERE id='navigation.transport-items' AND category_id='navigation' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Airships',description='Airship routes use only declared schedules, stops, and current server-observed boarding/transit events; the planner must not assume arrival from elapsed time alone.',acceptance_criteria_json='["A supported-server fixture must exercise boarding, stop selection, and arrival confirmation; missing schedule or lost transit state must suspend the route and report uncertainty. Keep sanitized event trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.airships' AND category_id='navigation' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Instances',description='Instance travel is scoped to the server-confirmed instance identifier and entry/exit transitions; stale instance state is cleared after exit or disconnect.',acceptance_criteria_json='["A protocol fixture must assert entry assigns the returned instance context and exit clears it; duplicate entry, expired instance, or disconnect must not reuse a prior instance route. Preserve transitions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.instances' AND category_id='navigation' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Portal updates',description='New server-observed portal data supersedes stale graph edges only after validation of source and destination fields.',acceptance_criteria_json='["A deterministic update fixture must add, change, and remove a portal edge while unrelated edges remain stable; malformed update must preserve prior graph. Keep graph diff output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.portal-updates' AND category_id='navigation' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Travel costs',description='Route cost totals the declared edge, item, or service costs using known inputs and marks routes with unknown cost instead of assigning zero.',acceptance_criteria_json='["A table-driven graph must verify exact cost sums and route choice; unknown or overflowing costs must produce an explicit unknown/error result. Preserve graph fixture and totals."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.travel-costs' AND category_id='navigation' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Alternative routes',description='When the preferred route is blocked or unavailable, the planner returns the next legal route ranked by declared cost and constraints, or an explicit no-route result.',acceptance_criteria_json='["A deterministic graph with a blocked preferred edge and two alternatives must assert the selected legal path and ordering; when all paths fail, return no route. Keep graph fixture and result."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Route.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='navigation.alternative-routes' AND category_id='navigation' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Target selection',description='The combat decision selects an eligible visible hostile actor using configured target filters and stable priority rules; dead, friendly, removed, or disallowed actors are never selected.',acceptance_criteria_json='["A deterministic actor set with mixed hostility, distance, and priority must produce the expected target; removal or death of the winner must select the next eligible actor or return no target. Preserve actor fixture and decision trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/mon_control.txt"]',updated_at=unixepoch() WHERE id='combat.target-selection' AND category_id='combat' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Physical attacks',description='A physical attack command is issued only for a live eligible target within the server-reported attack state and after any required approach; completion is confirmed by combat events, not by command send.',acceptance_criteria_json='["A combat event fixture must assert command gating, accepted attack response, and target/HP reconciliation; range failure, target removal, or server rejection must not report a hit. Keep sanitized event sequence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/mon_control.txt"]',updated_at=unixepoch() WHERE id='combat.physical-attacks' AND category_id='combat' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Approach',description='When a target lies beyond usable attack range, movement selects a reachable position that satisfies range and walkability without crossing obstacles.',acceptance_criteria_json='["Deterministic field/actor fixtures must assert the approach endpoint is walkable and within attack range; blocked target or no legal path must yield a no-approach result and no movement command. Preserve positions and route."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/mon_control.txt"]',updated_at=unixepoch() WHERE id='combat.approach' AND category_id='combat' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Attack range',description='The attack decision compares confirmed character-to-target distance with the active weapon or skill range and does not attack outside that range.',acceptance_criteria_json='["Boundary tests at range-minus-one, exact range, and range-plus-one must match the declared metric; unknown range must defer action rather than assume melee reach. Keep table-driven distance assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/mon_control.txt"]',updated_at=unixepoch() WHERE id='combat.attack-range' AND category_id='combat' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Monster priorities',description='Configured monster rules rank only eligible targets, honoring explicit ignore, attack, and priority entries before fallback order.',acceptance_criteria_json='["A fixture with overlapping allow/ignore/priority rules must yield a deterministic ordered target list; conflicting or malformed rules are reported and cannot elevate an ignored monster. Preserve rule fixture and ranked output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/mon_control.txt"]',updated_at=unixepoch() WHERE id='combat.monster-priorities' AND category_id='combat' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Line of sight',description='Ranged attacks or skills are permitted only when the map''s line-of-sight rule confirms the segment is unobstructed.',acceptance_criteria_json='["A deterministic grid fixture must accept clear lines and reject lines blocked by each relevant obstacle; out-of-map or missing visibility data must fail closed. Keep field fixtures and visibility results."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/mon_control.txt"]',updated_at=unixepoch() WHERE id='combat.line-of-sight' AND category_id='combat' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Target switching',description='The active target changes only when it becomes invalid, a configured priority rule requires a switch, or the operator requests one; the previous target''s action is cancelled first.',acceptance_criteria_json='["A fake combat sequence must assert switch reasons, cancel-before-select ordering, and no switch on irrelevant actor updates; rejected new targets leave a safe no-target state. Preserve event trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/mon_control.txt"]',updated_at=unixepoch() WHERE id='combat.target-switching' AND category_id='combat' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Give up on a target',description='The controller abandons a target only after a configured condition such as unreachable path, timeout, or explicit filter and records why it stopped pursuing it.',acceptance_criteria_json='["Clock/route fixtures must trigger each enabled give-up condition and avoid premature abandonment when progress occurs; the next decision must not immediately reacquire an ignored target. Keep reason and target-selection assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/mon_control.txt"]',updated_at=unixepoch() WHERE id='combat.give-up-on-a-target' AND category_id='combat' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Advanced positioning',description='The planner chooses a legal combat position satisfying configured distance, obstacle, and hazard constraints rather than moving directly onto the target.',acceptance_criteria_json='["A deterministic arena fixture must compare candidate tiles and select one meeting all constraints; if none exist, combat pauses and reports no valid position. Preserve map fixture and selected coordinates."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/PathFinding.pm"]',updated_at=unixepoch() WHERE id='combat.advanced-positioning' AND category_id='combat' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Ranged combat',description='A ranged action uses the equipped weapon/ammunition and requires visible target, valid range, and sufficient resources before sending an attack.',acceptance_criteria_json='["Inventory, range, and visibility fixtures must allow a valid shot and reject missing ammunition, blocked line, and out-of-range cases without consuming resources locally. Keep decision and server response assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Skill.pm"]',updated_at=unixepoch() WHERE id='combat.ranged-combat' AND category_id='combat' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Kiting',description='Kiting alternates a confirmed ranged action with movement that increases separation while preserving a reachable safe route and the configured attack window.',acceptance_criteria_json='["A deterministic actor/field sequence must show attack only when range conditions are met and retreat only after action/position events; blocked retreat or lost target stops the loop. Preserve timeline and route results."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/mon_control.txt"]',updated_at=unixepoch() WHERE id='combat.kiting' AND category_id='combat' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Tank mode',description='tankMode selects the configured protection behavior for eligible allies or targets and does not redirect attacks toward unrelated actors.',acceptance_criteria_json='["A party/combat fixture must exercise matching and nonmatching entities and verify only the configured target is protected; stale party membership or invalid target disables tank action. Keep config and decision trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt"]',updated_at=unixepoch() WHERE id='combat.tank-mode' AND category_id='combat' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Conditional equipment',description='Equipment changes occur only when the active condition matches, the item is present, and the server confirms the switch; combat does not assume an unacknowledged item is equipped.',acceptance_criteria_json='["A rule fixture must verify match/no-match cases and server acknowledgment updates; missing item, conflicting rules, or denial preserves confirmed equipment state. Save rule and response assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt"]',updated_at=unixepoch() WHERE id='combat.conditional-equipment' AND category_id='combat' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Cooperative combat',description='Group combat uses only current party/actor observations to avoid duplicate or conflicting target assignments and honors each character''s independent authorization.',acceptance_criteria_json='["A multi-actor simulation must assert deterministic assignment and release on death/disconnect; stale member state or unavailable target must not cause an attack command. Retain simulation trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/mon_control.txt"]',updated_at=unixepoch() WHERE id='combat.cooperative-combat' AND category_id='combat' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Advanced attack conditions',description='Advanced attack conditions are evaluated from typed current facts and produce a documented allow/deny reason before any attack is sent.',acceptance_criteria_json='["Table-driven condition fixtures must cover each supported operator, missing fact, and conflict; only a true condition emits an action, while evaluation errors fail closed. Keep condition inputs and decision results."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/mon_control.txt"]',updated_at=unixepoch() WHERE id='combat.advanced-attack-conditions' AND category_id='combat' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Targeted skills',description='A targeted skill request names the intended actor and is sent only when the skill is learned, available, and the target satisfies its target type.',acceptance_criteria_json='["Skill-state and packet fixtures must assert the encoded target ID and accepted effect event; unknown target, insufficient resource, cooldown, and server rejection must not be reported as a cast. Keep sanitized packet trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Skill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/UseSkill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='skills.targeted-skills' AND category_id='skills' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Coordinate-targeted skills',description='A ground-targeted skill uses a validated map coordinate and respects its area and field restrictions; it does not substitute the character''s current target coordinates.',acceptance_criteria_json='["Coordinate boundary fixtures must assert accepted encoding within map bounds and reject out-of-bounds or forbidden cells; an authorized server response must confirm cast effect. Preserve fixture and response evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Skill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/UseSkill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='skills.coordinate-targeted-skills' AND category_id='skills' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Offensive skills',description='An offensive skill is chosen only when its configured condition, target eligibility, resource cost, range, and cooldown all pass.',acceptance_criteria_json='["A deterministic rule fixture must identify the selected skill and exact cost checks; rejected casts and unmet conditions must leave the attack task active without claiming damage. Keep decision table and event result."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Skill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/UseSkill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='skills.offensive-skills' AND category_id='skills' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Self-healing',description='A self-heal is considered when the configured HP/SP condition is met and the skill is available; success is recognized only from server status change.',acceptance_criteria_json='["A fake-status sequence must trigger at the threshold and not above it; a protocol fixture must confirm HP/SP changes, while insufficient resource or interruption leaves the prior status. Save threshold and packet assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Skill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/UseSkill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='skills.self-healing' AND category_id='skills' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Self buffs',description='Configured self-buffs are applied only when their status is absent or due for refresh and the character meets the skill''s resource/prerequisite rules.',acceptance_criteria_json='["Clock-controlled status fixtures must prevent duplicate casts while active and schedule a refresh only at the configured boundary; denied/interrupted casts remain pending or error. Keep status and cast trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Skill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/UseSkill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='skills.self-buffs' AND category_id='skills' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Cooldowns',description='Skill availability becomes blocked for the server-reported or configured cooldown interval and becomes available only when the interval expires or a reset event is received.',acceptance_criteria_json='["Fake-clock tests must verify unavailable just before expiry and available at expiry; duplicate casts cannot bypass the timer, and a disconnect does not falsely clear a server-confirmed cooldown. Retain timeline."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Skill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/UseSkill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='skills.cooldowns' AND category_id='skills' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Cast time',description='A cast remains pending for its reported or configured duration and is complete only after the server confirms success; interruption or cancellation terminates it without applying an effect.',acceptance_criteria_json='["A clock-controlled cast fixture must assert start, completion, and interrupted paths; the effect event must be absent after cancellation. Keep event ordering evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Skill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/UseSkill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='skills.cast-time' AND category_id='skills' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Combos',description='A combo executes the next skill only when the previous skill''s server response satisfies the combo transition and each skill remains eligible.',acceptance_criteria_json='["A deterministic two/three-skill sequence must assert response-driven ordering; timeout, denial, target change, or missing resource terminates the combo without sending later steps. Preserve sequence trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt"]',updated_at=unixepoch() WHERE id='skills.combos' AND category_id='skills' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Party skills',description='A party skill targets only eligible current party members under its configured condition and never treats nonmembers as recipients.',acceptance_criteria_json='["A party membership fixture plus authorized protocol test must verify recipient selection and server-confirmed effects; stale membership and rejected cast must not be recorded as success. Keep sanitized packet trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/SlaveAttack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt"]',updated_at=unixepoch() WHERE id='skills.party-skills' AND category_id='skills' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Monster skills',description='Configured monster-skill rules trigger only for matching observed monster events and honor target, range, and resource constraints.',acceptance_criteria_json='["A synthetic monster event stream must exercise matching and nonmatching rules; a server fixture confirms the cast, while stale actor IDs or unavailable resources suppress it. Preserve rule fixture and outcomes."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt"]',updated_at=unixepoch() WHERE id='skills.monster-skills' AND category_id='skills' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Advanced conditions',description='Skill conditions evaluate only supported fields and operators against a consistent snapshot; unknown fields or malformed expressions return an explicit configuration error.',acceptance_criteria_json='["A table-driven parser/evaluator suite must assert known true/false expressions and reject unknown names, malformed syntax, and missing required values without casting. Keep expression fixtures and diagnostics."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Skill.pm"]',updated_at=unixepoch() WHERE id='skills.advanced-conditions' AND category_id='skills' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Equipment requirements',description='A skill cast is eligible only when required equipment is confirmed equipped and its prerequisites are met.',acceptance_criteria_json='["Inventory/status fixtures must distinguish confirmed versus merely requested equipment; unmet equipment blocks the cast, and a server cast rejection remains an error. Preserve equipment/decision snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Skill.pm"]',updated_at=unixepoch() WHERE id='skills.equipment-requirements' AND category_id='skills' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Interruptions',description='A server interruption, movement, cancellation, or timeout ends the pending cast exactly once and prevents subsequent logic from assuming the skill effect occurred.',acceptance_criteria_json='["Event-sequence tests must cover each interruption cause and assert one terminal cast state with no effect event; a late completion packet must be treated as stale. Keep ordered trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/UseSkill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='skills.interruptions' AND category_id='skills' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Special class skills',description='Class-specific skills are exposed only for classes and protocol profiles with verified skill metadata, target rules, and resource costs.',acceptance_criteria_json='["Per-profile skill fixtures must assert supported class/skill combinations and reject unsupported IDs without sending a packet; supported casts require server confirmation. Store profile matrix and packet evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Skill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/UseSkill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='skills.special-class-skills' AND category_id='skills' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Persistent skills',description='Persistent effects remain active while server status confirms them and are refreshed or stopped according to explicit configuration, not a local timer alone.',acceptance_criteria_json='["Status event tests must cover activation, refresh, expiry, disconnect, and explicit stop; a cast request alone must not mark persistence active. Keep clocked state transitions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Skill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/UseSkill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='skills.persistent-skills' AND category_id='skills' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Option selection',description='A skill choice resolves from the configured option list to a valid protocol option for that skill and target; unknown options are rejected before transmission.',acceptance_criteria_json='["Option parsing tests must map each supported value to its expected packet field and reject misspellings or unsupported combinations; preserve mapping table and encoded-packet assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Skill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/UseSkill.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='skills.option-selection' AND category_id='skills' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Broad skill block compatibility',description='Supported skill blocks retain their documented OpenKore control fields, ordering, default behavior, and condition semantics for the declared compatibility subset.',acceptance_criteria_json='["Compatibility fixtures extracted from supported control blocks must parse and make the same eligible/ineligible decision; unsupported fields are reported by name and cannot be silently ignored. Keep fixture provenance and comparison output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt"]',updated_at=unixepoch() WHERE id='skills.broad-skill-block-compatibility' AND category_id='skills' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Scheduler',description='The scheduler selects a runnable decision task from current session events without blocking the network loop and preserves deterministic ordering for equal-priority work.',acceptance_criteria_json='["A fake-clock/event-loop test must show queued work runs in declared order and event processing remains available while a task waits; task failure is surfaced without starving later safe work. Keep scheduler trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.scheduler' AND category_id='ai' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Task queue',description='Queued actions retain their declared dependencies and are executed once only after prerequisites complete; cancellation removes pending work and releases owned resources.',acceptance_criteria_json='["A deterministic queue fixture must assert dependency ordering, exactly-once completion, and cancellation of queued/running tasks; failed prerequisite must prevent dependent execution. Preserve queue trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.task-queue' AND category_id='ai' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Automatic AI mode',description='Automatic mode starts eligible configured routines after session synchronization and stops issuing actions when the session becomes invalid.',acceptance_criteria_json='["State-machine tests must start automation only after a confirmed in-game state and stop on disconnect/death/pause; record action and state ordering."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.automatic-ai-mode' AND category_id='ai' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Manual AI mode',description='Manual mode accepts explicit operator actions but does not launch autonomous target, movement, or item loops.',acceptance_criteria_json='["A command-routing test must allow a permitted manual action and prove background automation remains idle; switching modes cancels outstanding automatic tasks. Keep task-state assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.manual-ai-mode' AND category_id='ai' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='AI off mode',description='AI off mode issues no autonomous game actions and cancels or pauses active automation tasks without closing the user''s session.',acceptance_criteria_json='["A deterministic event stream with AI off must produce zero autonomous commands; queued tasks must be stopped and no delayed action may fire after mode change. Preserve command log."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.ai-off-mode' AND category_id='ai' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Cancellation',description='Cancellation propagates to child tasks, pending timers, and transport requests and leaves each task in one terminal cancelled state.',acceptance_criteria_json='["Nested-task tests must cancel at each stage and assert no child or timer sends later work; repeated cancellation is idempotent. Keep task lifecycle output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.cancellation' AND category_id='ai' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Timeouts',description='A task timeout uses an injected monotonic clock and reports the timed-out operation while cancelling its pending work.',acceptance_criteria_json='["Fake-clock tests must prove completion before deadline succeeds and expiry at deadline times out once; a late response cannot revive the task. Preserve event timestamps."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.timeouts' AND category_id='ai' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Priorities',description='Configured priorities order eligible tasks consistently while respecting hard safety constraints and preventing starvation of lower-priority work.',acceptance_criteria_json='["A deterministic scheduler fixture with competing tasks must match expected priority/tie order and aging policy; invalid priority configuration is rejected before scheduling. Keep schedule trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/priority.txt"]',updated_at=unixepoch() WHERE id='ai.priorities' AND category_id='ai' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='HP/SP recovery',description='Configured HP/SP thresholds trigger the selected recovery action using current confirmed status and available resources, then wait for server status before clearing the recovery need.',acceptance_criteria_json='["Threshold fixtures must test below/at/above limits and confirm status reconciliation; no item/skill or server denial must remain an explicit unmet recovery condition. Preserve decisions and response events."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt"]',updated_at=unixepoch() WHERE id='ai.hp-sp-recovery' AND category_id='ai' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Automatic item use',description='An item-use rule consumes an eligible item only when its condition matches and the server confirms use; inventory counts change from authoritative updates.',acceptance_criteria_json='["A mocked inventory/status sequence must trigger exactly at configured conditions and reconcile quantity only after server response; absent item or denial cannot report recovery. Keep inventory diff and packet result."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt"]',updated_at=unixepoch() WHERE id='ai.automatic-item-use' AND category_id='ai' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Resting',description='Resting begins only when configured safety conditions permit and stops on a relevant threat, movement request, or recovery threshold event.',acceptance_criteria_json='["A fake event/clock test must enter and leave rest at the declared conditions; hostile actor appearance or invalid map state must cancel rest before another autonomous action. Preserve timeline."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.resting' AND category_id='ai' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Error recovery',description='Recoverable task errors invoke bounded, category-specific recovery while fatal/auth/configuration errors stop automation and remain visible to the operator.',acceptance_criteria_json='["Injected error tests must assert retry only for declared recoverable classes, bounded attempts, and stop behavior for fatal errors; retain error classification and recovery trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.error-recovery' AND category_id='ai' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Combat coordination',description='Combat actions yield or resume according to target state, movement readiness, cast completion, and queued loot work so automation does not issue incompatible concurrent commands or preempt an active collection task.',acceptance_criteria_json='["A deterministic task-queue fixture must show that a configured automatic take/gather mode with matching loot work queued suppresses a new auto-attack until that work drains, while no matching queued loot leaves attack eligibility governed by target and timeout rules. Preserve the config, queue trace, and dispatch assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.combat-coordination' AND category_id='ai' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Navigation coordination',description='Navigation owns movement until the destination is confirmed or the route is cancelled; combat, dialogs, or map changes suspend or replan movement explicitly.',acceptance_criteria_json='["A multi-event simulation must assert no stale step after target/map/dialog changes and completion only after arrival confirmation; save event/route trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.navigation-coordination' AND category_id='ai' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Storage coordination',description='Storage actions run only at a confirmed storage interaction state and suspend unrelated automation until item counts are reconciled or the storage task fails.',acceptance_criteria_json='["A fake NPC/storage exchange must verify open, transfer, reconcile, close ordering; disconnect or menu mismatch must stop the routine without claiming final counts. Keep state and inventory diffs."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm"]',updated_at=unixepoch() WHERE id='ai.storage-coordination' AND category_id='ai' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Buying coordination',description='Purchase actions use the active buy rule, budget, inventory capacity, and current currency, and wait for server-reported inventory/currency changes.',acceptance_criteria_json='["A transaction fixture must compute eligible quantity and reconcile the server reply; insufficient funds, capacity, or refusal must leave purchase incomplete. Preserve request and inventory snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.buying-coordination' AND category_id='ai' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Selling coordination',description='Sale actions exclude protected/required items, respect configured quantities, and update inventory/currency only from server confirmation.',acceptance_criteria_json='["A fixture with protected and sellable stacks must request only allowed quantities and reconcile accepted counts; refusal or partial sale must be reflected exactly. Keep rule fixture and result."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.selling-coordination' AND category_id='ai' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Automatic configuration switching',description='A profile switch occurs only when its trigger matches and atomically replaces the relevant effective configuration before new decisions run.',acceptance_criteria_json='["Deterministic trigger tests must assert selected profile and no mixed old/new decision fields; invalid profile or failed load must retain the prior active configuration. Preserve profile snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task.pm"]',updated_at=unixepoch() WHERE id='ai.automatic-configuration-switching' AND category_id='ai' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Profiles',description='A named profile loads its own validated settings and remains isolated from other profiles unless an explicit shared setting is defined.',acceptance_criteria_json='["Two profile fixtures must produce distinct effective values and switching back must restore the original; missing or malformed profile reports the field and keeps current settings. Keep fixture diff."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/profiles/profiles.pl"]',updated_at=unixepoch() WHERE id='ai.profiles' AND category_id='ai' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Conditional commands',description='A conditional command executes only when its parsed predicate evaluates true against the current snapshot and rejects unknown commands or malformed predicates.',acceptance_criteria_json='["Parser/evaluator fixtures must show true executes once, false executes zero times, and unknown/malformed inputs produce a diagnostic without side effects. Preserve expressions and action trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/macro/macro.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='ai.conditional-commands' AND category_id='ai' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Composite automations',description='A composite routine runs its declared stages in order, passes explicit outputs between them, and stops dependent stages after a failure or cancellation.',acceptance_criteria_json='["A deterministic multi-stage fixture must assert order, value handoff, and failure/cancellation propagation; final success is emitted only after all required stages complete. Keep execution trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Chained.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm"]',updated_at=unixepoch() WHERE id='ai.composite-automations' AND category_id='ai' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Inventory contents',description='The inventory view is keyed by server item identity and reflects the latest authoritative inventory snapshot and deltas; items disappear only after a server update.',acceptance_criteria_json='["Snapshot/delta fixtures must produce the exact item set and preserve unrelated stacks; duplicate, missing, or malformed deltas must not lose items silently. Keep before/after inventory snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Inventory.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='inventory.inventory-contents' AND category_id='inventory' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Item quantities',description='Stack quantities are updated from server inventory events and never become negative or exceed the reported stack limit.',acceptance_criteria_json='["Table-driven add/remove/split/merge events must yield exact counts; duplicate or oversized deltas must return an explicit inconsistency and retain the last valid quantity. Preserve event sequence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Inventory.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='inventory.item-quantities' AND category_id='inventory' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Weight tracking',description='Carried weight is derived from item quantities and verified item weights or the server-reported weight, with unknown item weight represented as unknown rather than zero.',acceptance_criteria_json='["A deterministic item table and inventory fixture must match expected total and capacity percentage; unknown weight and conflicting server totals must be surfaced. Keep source fixture and computed result."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Inventory.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='inventory.weight-tracking' AND category_id='inventory' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Item consumption',description='Item use is allowed only for a present, usable stack and requested quantity; consumption is finalized from the server response or inventory delta.',acceptance_criteria_json='["A fake inventory/protocol test must assert correct item ID/count and reconcile accepted, rejected, and partial-use responses; no local decrement occurs on send alone. Preserve packet and inventory diff."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Inventory.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='inventory.item-consumption' AND category_id='inventory' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Equipment identification',description='Equipment entries preserve server item ID, equip location, refinement/options, and identified state without treating ordinary consumables as equipment.',acceptance_criteria_json='["Golden inventory packets must decode each equipment field and distinguish equipped, unequipped, and unidentified items; malformed option data must not corrupt other entries. Keep fixtures and decoded records."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Inventory.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='inventory.equipment-identification' AND category_id='inventory' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Equip',description='Equip sends a request only for a present item compatible with the requested slot and marks it equipped after server confirmation.',acceptance_criteria_json='["A protocol fixture must accept one legal slot and reject incompatible/missing items; denied equip leaves the prior confirmed equipment view unchanged. Preserve request and response."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Inventory.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='inventory.equip' AND category_id='inventory' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Unequip',description='Unequip targets a currently equipped item and updates its slot only after the server confirms removal.',acceptance_criteria_json='["State fixture and server response must prove successful slot clearing; rejection or late response must preserve the confirmed equipped state. Keep equipment snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Inventory.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='inventory.unequip' AND category_id='inventory' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='equipAuto',description='equipAuto selects the highest matching configured equipment rule for the current context without equipping a missing or slot-incompatible item.',acceptance_criteria_json='["Rule precedence tests with context and inventory fixtures must choose the expected item/slot; no match or server rejection leaves current equipment intact. Preserve rules and decision output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='inventory.equipauto' AND category_id='inventory' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='autoSwitch',description='autoSwitch changes equipment only when its declared trigger becomes active and restores or selects the next rule when that trigger ends.',acceptance_criteria_json='["Clock/event fixtures must exercise trigger enter/exit and competing rules; requests must be serialized and effective equipment changes require server acknowledgment. Keep timeline and slot state."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='inventory.autoswitch' AND category_id='inventory' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Ammunition',description='Ranged attacks require the compatible ammunition type and quantity for the equipped weapon, and ammo state changes only from server inventory updates.',acceptance_criteria_json='["Weapon/ammo matrix tests must allow compatible combinations, reject incompatible or empty stacks, and reconcile consumption after a confirmed attack. Keep matrix and inventory evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Inventory.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/Attack.pm"]',updated_at=unixepoch() WHERE id='inventory.ammunition' AND category_id='inventory' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Cart',description='Cart contents and weight track server-confirmed cart snapshots and transfers independently from the carried inventory.',acceptance_criteria_json='["Cart packet fixtures must update only cart records and reconcile transfer deltas; duplicate or rejected transfer cannot double-count either side. Preserve both inventory snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Cart.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='inventory.cart' AND category_id='inventory' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Item identification',description='An unidentified item remains marked unidentified until a supported identify operation is confirmed by server data; candidate name is not inferred from item ID alone.',acceptance_criteria_json='["A protocol fixture must transition one item after confirmation and leave it unchanged on failure; unknown identify response must remain explicitly unresolved. Keep sanitized request/response evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt"]',updated_at=unixepoch() WHERE id='inventory.item-identification' AND category_id='inventory' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Cards',description='Card slots and card identities are retained from equipment data and shown only when the server packet supplies those values.',acceptance_criteria_json='["Golden equipment fixtures must distinguish empty and populated slots and map known IDs; unknown card IDs remain labeled unknown without altering equipment identity. Preserve packet fixture."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Inventory.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='inventory.cards' AND category_id='inventory' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Repair',description='Repair requests target a server-reported damaged item and mark it repaired only after an accepted repair response or updated durability state.',acceptance_criteria_json='["A local protocol fixture must cover damaged, undamaged, accepted, and rejected repair cases; no repair fee/item change is reported until confirmed. Keep request/result trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='inventory.repair' AND category_id='inventory' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Refinement',description='Refinement requests respect the supported item/material requirements and use server response to reconcile success, failure, and item loss.',acceptance_criteria_json='["An authorized-server fixture must cover accepted and failed refinement responses and assert exact inventory/equipment changes; timeout must remain unknown rather than assumed success. Preserve sanitized trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='inventory.refinement' AND category_id='inventory' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Supported enchantments',description='Only enchantment types with confirmed profile-specific metadata are parsed and displayed; unsupported option encodings remain preserved as unknown values.',acceptance_criteria_json='["Option fixtures must decode supported values exactly and round-trip unknown values without mislabeling; preserve the metadata version and assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Inventory.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='inventory.supported-enchantments' AND category_id='inventory' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Item combination',description='Combination actions require a configured supported recipe and all required input quantities, and resulting inventory is accepted only from the server response.',acceptance_criteria_json='["Recipe/input fixtures must calculate exact required quantities and reconcile accepted/failed outcomes; missing inputs and unknown recipes cannot send a request. Keep recipe fixture and inventory diff."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Inventory.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='inventory.item-combination' AND category_id='inventory' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Item detection',description='Ground-item events create loot candidates with server identity, map position, and expiration state; disappeared or unrecognized entities are not treated as collectible.',acceptance_criteria_json='["A deterministic spawn/move/disappear event sequence must expose exactly the active ground items and clear expired IDs; preserve decoded fixture and candidate snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Item.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/pickupitems.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='loot.item-detection' AND category_id='loot' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Item collection',description='Collection is requested only when the item remains visible, reachable, and allowed by filters; possession is confirmed by inventory update rather than pickup request.',acceptance_criteria_json='["A field/item fixture must route to a valid item and reconcile its inventory arrival; blocked path, item disappearance, or server denial returns a failed/expired collection result. Keep event trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Item.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/pickupitems.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='loot.item-collection' AND category_id='loot' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Loot filters',description='Configured pickup rules classify each item as allowed, ignored, or protected using explicit precedence and the current map/inventory context.',acceptance_criteria_json='["Table-driven item metadata and rule fixtures must assert each class and precedence; malformed rules fail configuration validation and default to no pickup. Preserve test matrix."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Item.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/pickupitems.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='loot.loot-filters' AND category_id='loot' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Loot priorities',description='Eligible ground items are ordered by configured priority with deterministic tie-breaking and without bypassing ignore/protection rules.',acceptance_criteria_json='["A fixture with competing item priorities must produce a stable order across runs; ignored items must never enter the ranked set. Keep rule fixture and ordered IDs."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Item.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/pickupitems.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='loot.loot-priorities' AND category_id='loot' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Weight control',description='Pickup decisions stop or change strategy at configured weight thresholds using reconciled current weight and item weight; unknown weight cannot be treated as spare capacity.',acceptance_criteria_json='["Boundary tests at threshold-minus/at/plus must select expected behavior; missing weight data pauses collection with an explicit unknown state. Preserve inventory fixture and decision."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Item.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/pickupitems.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='loot.weight-control' AND category_id='loot' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Independent gathering',description='When no combat or route task owns the character, gathering may select a valid ground item and return control after confirmation or bounded failure.',acceptance_criteria_json='["A scheduler simulation must prove gathering yields to higher-priority tasks and completes only after inventory confirmation; stale item or no route ends the attempt. Keep task lifecycle trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Item.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/pickupitems.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='loot.independent-gathering' AND category_id='loot' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Greed',description='Greed is issued only when the skill is learned, resource-ready, permitted by the active rules, and has eligible nearby items.',acceptance_criteria_json='["A skill/actor fixture must assert eligible item set and request gating; unavailable skill, no items, or server rejection must not add loot to inventory. Preserve decision and response."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='loot.greed' AND category_id='loot' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Storage integration',description='Loot policy may route carried items to storage only when a configured storage rule matches and storage access is confirmed.',acceptance_criteria_json='["Inventory/storage fixtures must select the expected stacks and reconcile storage deltas; failed access or capacity limits leave remaining items recorded as carried. Keep both snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Storage.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm"]',updated_at=unixepoch() WHERE id='loot.storage-integration' AND category_id='loot' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Advanced collection rules',description='Advanced collection expressions are parsed into supported predicates and evaluated against current item, map, and capacity facts before pickup.',acceptance_criteria_json='["Expression fixtures must assert matching/nonmatching results and reject unknown fields/operators; evaluation failure prevents collection. Preserve expressions and decision evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Item.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/pickupitems.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='loot.advanced-collection-rules' AND category_id='loot' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Group collection',description='Group collection avoids claiming an item already confirmed collected or reserved by another authorized group member when such status is available.',acceptance_criteria_json='["A multi-client simulation must assign each ground item at most once and release assignment on member disconnect; missing coordination evidence falls back to safe individual rules. Keep simulation trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Item.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/pickupitems.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/items_control.txt"]',updated_at=unixepoch() WHERE id='loot.group-collection' AND category_id='loot' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='NPC detection',description='NPC spawn/update packets create a visible NPC candidate at the reported map coordinate; an NPC is removed only on a corresponding server disappearance or map reset.',acceptance_criteria_json='["A packet fixture must assert NPC identity, position, and removal behavior; malformed updates and unknown IDs must not create a false interactable record. Preserve decoded packet assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/NPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='npcs.npc-detection' AND category_id='npcs' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='NPC identification',description='An NPC receives a stable name only from configured map data or a supported server name response, with unresolved entities remaining explicitly unnamed.',acceptance_criteria_json='["Fixture tests must map known ID/location to its configured name and preserve unknown labels when no mapping exists; keep data fixture and lookup result."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/NPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='npcs.npc-identification' AND category_id='npcs' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='NPC dialogue',description='A dialogue task sends each interaction step only after the previous NPC response, and completes only on a recognized terminal response.',acceptance_criteria_json='["An authorized dialogue fixture must assert ordered talk/reply events and a final completion response; disconnect, unexpected packet, or NPC loss ends with a named error. Keep sanitized transcript."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/NPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='npcs.npc-dialogue' AND category_id='npcs' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='NPC menus',description='Menu choices are selected by the server-presented option list and verified option identity, not by assuming a fixed menu index across servers.',acceptance_criteria_json='["Two menu fixtures with reordered options must select the configured semantic option correctly; unknown/missing choice aborts before sending. Preserve menu and encoded choice."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/NPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='npcs.npc-menus' AND category_id='npcs' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='TalkNPC',description='TalkNPC commands parse the declared NPC target and step sequence, resolve the target on the active map, and stop on timeout or unexpected dialogue state.',acceptance_criteria_json='["Command parser and authorized protocol tests must assert target resolution and sequence; unknown NPC or unexpected menu returns an explicit step failure. Keep sanitized command and transcript."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/NPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='npcs.talknpc' AND category_id='npcs' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Numeric responses',description='Numeric dialogue responses are sent only when the server''s current prompt requests a number and the configured value satisfies its declared bounds.',acceptance_criteria_json='["Prompt fixtures must allow an in-range numeric response and reject text prompts, out-of-range values, and stale prompt IDs. Preserve request/response assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/NPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='npcs.numeric-responses' AND category_id='npcs' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Text responses',description='Text dialogue responses preserve the configured string encoding and are sent only for a prompt that accepts text.',acceptance_criteria_json='["Encoding fixtures must round-trip supported text and reject overlength or unsupported bytes; an authorized server reply confirms acceptance. Keep fixture bytes and sanitized dialogue trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/NPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='npcs.text-responses' AND category_id='npcs' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Quest tracking',description='Quest records update from server-reported quest IDs, objective progress, and completion events; command intent alone does not alter progress.',acceptance_criteria_json='["Golden quest packets must update the correct quest/objective and ignore unknown IDs without inventing completion; preserve packet fixture and state snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='npcs.quest-tracking' AND category_id='npcs' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Conditional dialogue',description='Conditional dialogue branches evaluate only from the current NPC prompt and configured facts, selecting a branch whose condition is true.',acceptance_criteria_json='["A decision fixture with true/false and missing facts must choose exactly one branch; ambiguous or unknown conditions stop the conversation with a diagnostic. Keep rule inputs and result."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/NPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='npcs.conditional-dialogue' AND category_id='npcs' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Dialogue failure recovery',description='On recoverable dialogue timeout or menu mismatch, the task may retry the declared safe step a bounded number of times and then stop without replaying completed choices.',acceptance_criteria_json='["Fake-clock transcript tests must prove retries and termination counts; NPC disappearance, disconnect, and non-retryable rejection stop immediately. Preserve step log."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/NPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='npcs.dialogue-failure-recovery' AND category_id='npcs' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Instances',description='NPC-based instance entry binds the session to the server-returned instance identity and clears it on confirmed exit or expiration.',acceptance_criteria_json='["An authorized packet fixture must assert instance entry/exit identity; refusal, stale entry response, or disconnect must not preserve an old instance. Keep sanitized event trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/NPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='npcs.instances' AND category_id='npcs' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Mission progress',description='Mission objectives advance only from the server''s quest/progress events and remain separate from locally inferred kills or collection attempts.',acceptance_criteria_json='["A quest event fixture must advance the specified objective once and ignore duplicate/unrelated events; preserve before/after progress records."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/NPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='npcs.mission-progress' AND category_id='npcs' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Mission rewards',description='A mission reward is recorded only when the server confirms the reward and its inventory/currency effects are reconciled.',acceptance_criteria_json='["An authorized completion fixture must verify reward response and corresponding item/currency update; failed claim or timeout remains pending/unknown and cannot be recorded as received. Keep sanitized response evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/NPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/TalkNPC.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='npcs.mission-rewards' AND category_id='npcs' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Open storage',description='Storage becomes accessible only after a server-confirmed storage-open interaction on a supported NPC/map; request send alone does not expose an empty local storage view.',acceptance_criteria_json='["A protocol fixture must test accepted open and server denial/menu mismatch; only accepted response enables transfer commands. Keep sanitized exchange and storage state."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Storage.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='storage.open-storage' AND category_id='storage' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Close storage',description='Closing storage stops further transfers and clears the active storage context only after server confirmation or confirmed connection teardown.',acceptance_criteria_json='["A sequence test must reject transfers after accepted close and preserve context after a rejected close until teardown; record response ordering."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Storage.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='storage.close-storage' AND category_id='storage' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Deposit items',description='Deposit requests use quantities available in inventory and storage capacity, then reconcile both inventories against server-reported transfer results.',acceptance_criteria_json='["A local storage exchange fixture must cover full, partial, and rejected deposit; exact item counts on both sides must match server replies. Preserve before/after snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Storage.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='storage.deposit-items' AND category_id='storage' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Withdraw items',description='Withdrawal requests do not exceed stored quantity or carried capacity, and resulting inventory changes only after the server confirms the transfer.',acceptance_criteria_json='["A deterministic capacity/quantity fixture plus protocol response must verify exact allowed quantity and reconcile partial/denied withdrawals. Keep item/capacity assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Storage.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='storage.withdraw-items' AND category_id='storage' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='storageAuto',description='storageAuto applies configured matching rules in order, honors protected items and quantities, and stops when the transfer is confirmed or an explicit blocker occurs.',acceptance_criteria_json='["Rule fixtures must select exact stacks and demonstrate stop on capacity, access denial, or no match; final counts must reconcile with storage response. Preserve config and inventory diff."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Storage.pm"]',updated_at=unixepoch() WHERE id='storage.storageauto' AND category_id='storage' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='getAuto',description='getAuto selects only configured items and quantities that fit current inventory/weight limits and are actually present in storage.',acceptance_criteria_json='["A fixture with shortages and capacity limits must compute bounded requests; server partial/denial leaves remaining need explicit and not marked fulfilled. Keep selection and response evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Storage.pm"]',updated_at=unixepoch() WHERE id='storage.getauto' AND category_id='storage' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Additional storage types',description='A storage subtype is exposed only when the active protocol profile identifies its distinct endpoint, fields, and access rules.',acceptance_criteria_json='["Per-profile fixtures must decode a declared subtype and reject unsupported subtype packets without merging records into ordinary storage; keep profile matrix."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Storage.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='storage.additional-storage-types' AND category_id='storage' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Item-based access',description='An item-based storage access flow consumes or uses the required access item only when the server permits the interaction, then opens a confirmed storage session.',acceptance_criteria_json='["Inventory/protocol fixtures must cover required item present/absent and server acceptance/denial; item count and storage state reconcile only from server data. Keep sanitized exchange."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Task/Teleport.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Storage.pm"]',updated_at=unixepoch() WHERE id='storage.item-based-access' AND category_id='storage' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Command-based access',description='A storage command resolves to a known storage action and valid target in the current session; unknown commands cannot issue network operations.',acceptance_criteria_json='["Parser tests must assert supported open/close/deposit/withdraw argument forms and reject invalid quantities or states before sending. Preserve command fixtures and action list."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Storage.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='storage.command-based-access' AND category_id='storage' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Storage password',description='A password challenge is answered only through the configured secure input path and is never written to logs or normal configuration diagnostics.',acceptance_criteria_json='["A local protocol fixture must validate accepted/rejected password responses and inspect captured diagnostics for redaction; password mismatch leaves storage closed. Keep only redacted evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='storage.storage-password' AND category_id='storage' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Guild storage',description='Guild storage is a separate permission-checked inventory whose access, transfer limits, and identity are confirmed by server responses.',acceptance_criteria_json='["An authorized profile fixture must demonstrate allowed access and a denied access case; no guild item is merged with personal storage before confirmation. Preserve sanitized response and separate snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Storage.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='storage.guild-storage' AND category_id='storage' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Storage failure recovery',description='Storage interruption returns the task to a reconciled state using the last server-confirmed counts and resumes only from a safe idempotent step.',acceptance_criteria_json='["Inject disconnect during open, transfer, and close; assert no transfer is replayed without checking counts and unresolved quantity is surfaced. Keep failure trace and reconciliation results."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Storage.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='storage.storage-failure-recovery' AND category_id='storage' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='NPC purchases',description='A purchase is sent only for an item listed by the current NPC shop and a quantity affordable under current currency/capacity; final stock and money come from the server response.',acceptance_criteria_json='["An authorized transaction fixture must assert selected price, quantity, and reconciled inventory/currency; sold-out, insufficient-funds, capacity, and refusal cases remain incomplete. Keep sanitized transaction trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Deal.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/shop.txt"]',updated_at=unixepoch() WHERE id='commerce.npc-purchases' AND category_id='commerce' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='NPC sales',description='A sale includes only eligible carried items and quantities accepted by the current NPC shop; protected items are excluded and currency is reconciled from the server.',acceptance_criteria_json='["A fixture with protected, sellable, and partial stack quantities must request only the allowed set; denial or partial sale must match reported inventory/money exactly. Preserve rule and response evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Deal.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/shop.txt"]',updated_at=unixepoch() WHERE id='commerce.npc-sales' AND category_id='commerce' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='buyAuto',description='buyAuto applies configured NPC purchase entries only while the correct shop is open and budget/weight constraints allow the requested quantities.',acceptance_criteria_json='["Rule and shop fixtures must compute bounded quantities and stop at budget/capacity; server refusal leaves the outstanding need visible. Keep selected entries and reconciled totals."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm"]',updated_at=unixepoch() WHERE id='commerce.buyauto' AND category_id='commerce' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='sellAuto',description='sellAuto applies configured sell entries while preserving protected/required stock and waits for authoritative shop results before updating counts.',acceptance_criteria_json='["A stack fixture must verify exclusions, requested amount, partial sale, and rejection; keep item-list fixture and resulting inventory diff."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm"]',updated_at=unixepoch() WHERE id='commerce.sellauto' AND category_id='commerce' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Character-to-character transactions',description='A character-to-character trade tracks offer, acceptance, and final server confirmation as distinct stages and records only the completed exchange.',acceptance_criteria_json='["A local protocol test must cover offer modification, cancel, partner mismatch, and accepted completion; inventory changes occur only after final confirmation. Preserve redacted event trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Deal.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/shop.txt"]',updated_at=unixepoch() WHERE id='commerce.character-to-character-transactions' AND category_id='commerce' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Vending',description='Vending advertises only currently available items and prices under supported profile rules and reconciles purchases from server transaction events.',acceptance_criteria_json='["A supported-server fixture must validate advertisement fields and one purchase; invalid price, item count, or server refusal must not create a completed sale. Keep sanitized packet evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='commerce.vending' AND category_id='commerce' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Buying stores',description='Buying-store offers validate requested items, quantities, currency, and server-supported limits before publication and reconcile fulfilled quantities from server events.',acceptance_criteria_json='["An authorized profile fixture must exercise valid and invalid offers and partial fulfillment; canceled or timed-out stores are not counted as fulfilled. Preserve sanitized offer/response trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Deal.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/shop.txt"]',updated_at=unixepoch() WHERE id='commerce.buying-stores' AND category_id='commerce' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Barter',description='Barter is available only for a server profile with a documented exchange schema; each offered and requested item is checked against that schema before confirmation.',acceptance_criteria_json='["A protocol fixture must validate exact item/quantity mapping for one supported barter exchange and reject unknown fields or insufficient stock; unresolved server semantics remain explicitly unsupported. Keep schema and sanitized trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Deal.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/shop.txt"]',updated_at=unixepoch() WHERE id='commerce.barter' AND category_id='commerce' AND milestone_id='rc' AND is_required=0;

UPDATE roadmap_features SET title='Shop search',description='Shop search decodes server-reported listings into seller, item, price, and location records and filters without modifying transaction state.',acceptance_criteria_json='["Golden listing fixtures must yield exact normalized records and filter results; malformed listing data is rejected and unknown server formats remain unavailable. Preserve fixtures and expected output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Deal.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/shop.txt"]',updated_at=unixepoch() WHERE id='commerce.shop-search' AND category_id='commerce' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Bank',description='Bank balance and transfer state reflect only server-confirmed transactions and remain distinct from carried currency.',acceptance_criteria_json='["An authorized profile fixture must verify deposit/withdraw amounts and reconcile both balances; denied, partial, or timed-out transfers cannot change local totals. Keep sanitized request/reply evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Deal.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/shop.txt"]',updated_at=unixepoch() WHERE id='commerce.bank' AND category_id='commerce' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='RodEx',description='RodEx messages/items are parsed from supported server responses and item claims are recorded only after a confirmed claim response.',acceptance_criteria_json='["A profile fixture must decode message metadata and test claim success, rejection, and missing attachment; item counts update only from inventory events. Preserve redacted packet evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='commerce.rodex' AND category_id='commerce' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Mail',description='Mail compose, send, receive, and attachment states follow server acknowledgments; unconfirmed sends or attachments are not shown as delivered or claimed.',acceptance_criteria_json='["An authorized mail fixture must cover accepted and rejected send plus attachment claim reconciliation; malformed recipient/attachment data is rejected before transmission. Keep sanitized trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Deal.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/shop.txt"]',updated_at=unixepoch() WHERE id='commerce.mail' AND category_id='commerce' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Auctions',description='Auction listings and bids are represented from server state, with bid acceptance and final outcome distinguished from local submission.',acceptance_criteria_json='["A supported-server fixture must test listing decode, accepted/rejected bid, and final result; stale price or timeout must not display a winning bid. Preserve redacted event sequence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Deal.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/shop.txt"]',updated_at=unixepoch() WHERE id='commerce.auctions' AND category_id='commerce' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Cash Shop where supported',description='Cash Shop functionality is enabled only for profiles whose packet and item semantics are confirmed, and purchase completion requires server confirmation.',acceptance_criteria_json='["A profile-specific fixture must verify catalog parsing and one accepted/denied purchase without exposing payment credentials; unsupported profiles report unavailable. Keep sanitized packet/state evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Deal.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/shop.txt"]',updated_at=unixepoch() WHERE id='commerce.cash-shop-where-supported' AND category_id='commerce' AND milestone_id='rc' AND is_required=0;

UPDATE roadmap_features SET title='Public chat',description='A public message is encoded using the active protocol''s text limits and reported as sent only after the transport/server accepts it; local display does not imply delivery.',acceptance_criteria_json='["Encoding and protocol fixtures must verify supported character and length boundaries; an authorized server test covers acceptance and rejection, with no log injection from message text. Keep redacted trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Party.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ChatQueue.pm"]',updated_at=unixepoch() WHERE id='social.public-chat' AND category_id='social' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Private messages',description='A private message is addressed to the selected recipient identity and preserves protocol encoding; a missing recipient or server refusal produces a visible delivery failure.',acceptance_criteria_json='["A local/authorized protocol fixture must verify recipient field and accepted/rejected responses; message content is not exposed in diagnostics beyond safe redaction. Preserve sanitized exchange."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Party.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ChatQueue.pm"]',updated_at=unixepoch() WHERE id='social.private-messages' AND category_id='social' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Party',description='Party membership and member identity are updated from server events, and only confirmed members are used for party automation.',acceptance_criteria_json='["A join/leave/disband event fixture must produce exact membership and reject duplicate/stale events; keep before/after party state."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Party.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ChatQueue.pm"]',updated_at=unixepoch() WHERE id='social.party' AND category_id='social' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Invitations',description='Party/guild invitations are accepted or declined only when the server presents a valid inviter and the configured/operator policy allows it.',acceptance_criteria_json='["A protocol fixture must exercise valid, unknown, duplicate, and expired invitations; unknown inviter or disabled policy sends no acceptance packet. Keep sanitized event assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Party.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ChatQueue.pm"]',updated_at=unixepoch() WHERE id='social.invitations' AND category_id='social' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Experience sharing',description='Experience-sharing mode is displayed from server-confirmed party state and is not inferred from a configuration request.',acceptance_criteria_json='["Party response fixtures must decode each supported sharing mode and reject unknown mode values without changing current membership state. Keep packet fixture."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Party.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ChatQueue.pm"]',updated_at=unixepoch() WHERE id='social.experience-sharing' AND category_id='social' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Item sharing',description='Item-sharing rules are represented from server-confirmed party settings and never cause a local item transfer assumption.',acceptance_criteria_json='["A party settings fixture must decode supported distribution modes; unknown or unsupported modes display unavailable and do not change inventory. Preserve decoder assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Party.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ChatQueue.pm"]',updated_at=unixepoch() WHERE id='social.item-sharing' AND category_id='social' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Follow',description='Follow movement tracks the selected party actor''s confirmed position and replans when that actor moves or disappears; it never treats intended leader coordinates as reached.',acceptance_criteria_json='["A deterministic leader movement stream must produce safe following steps and stop on actor loss, map mismatch, or no route. Keep leader/route timeline."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Party.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ChatQueue.pm"]',updated_at=unixepoch() WHERE id='social.follow' AND category_id='social' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Group support',description='Group support selects only eligible current members and coordinates healing/buffs from confirmed status, respecting skill conditions and cooldowns.',acceptance_criteria_json='["A multi-member status fixture must choose the expected target and suppress duplicate support; stale membership, missing status, or denied cast must not mark the member supported. Preserve decision and response trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Party.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ChatQueue.pm"]',updated_at=unixepoch() WHERE id='social.group-support' AND category_id='social' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Guilds',description='Guild membership and guild events are scoped to the server-confirmed guild identity and are cleared or updated on authoritative membership events.',acceptance_criteria_json='["Golden packet fixtures must cover join/leave and relevant identity fields; stale guild data after leaving must not drive group actions. Keep state snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='social.guilds' AND category_id='social' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Clans',description='Clan entities are parsed only when the active server profile provides clan-specific packet semantics, remaining separate from guild state.',acceptance_criteria_json='["A supported-profile fixture must decode one clan membership/update and ensure it cannot overwrite guild identity; unsupported profiles keep clan data unavailable. Preserve profile fixture."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Party.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ChatQueue.pm"]',updated_at=unixepoch() WHERE id='social.clans' AND category_id='social' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Friends',description='Friend records update from server responses and identify the associated account/character without confusing a friend entry with a currently visible actor.',acceptance_criteria_json='["A fixture must test online/offline and removal events; unknown IDs remain unlinked and do not create actor records. Keep decoded list and actor map assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Party.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ChatQueue.pm"]',updated_at=unixepoch() WHERE id='social.friends' AND category_id='social' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Chat rooms',description='Chat-room state reflects server-confirmed room membership, title, and participant updates; joining or leaving is not assumed from a request alone.',acceptance_criteria_json='["Protocol fixtures must test create/join/leave and participant updates with one rejection path; stale room IDs cannot retain membership. Preserve sanitized transcript."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='social.chat-rooms' AND category_id='social' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Guild skills',description='Guild skill use requires confirmed guild membership, the required skill state, and server-permitted target/context.',acceptance_criteria_json='["Skill and guild fixtures must assert request gating and server-confirmed effect; nonmember, cooldown, or denial prevents success. Keep rule and response evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Party.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ChatQueue.pm"]',updated_at=unixepoch() WHERE id='social.guild-skills' AND category_id='social' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Alliances',description='Alliance relationships are represented from server events with source guild identity and relationship status; unknown updates do not establish trusted links.',acceptance_criteria_json='["A protocol fixture must add/change/remove one alliance and preserve unrelated guilds; unknown IDs remain explicitly unresolved. Keep event snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Party.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ChatQueue.pm"]',updated_at=unixepoch() WHERE id='social.alliances' AND category_id='social' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Pet detection',description='A pet actor is created and removed from server-reported pet identity and status packets, separate from ordinary monsters and players.',acceptance_criteria_json='["Pet lifecycle packet fixtures must create, update, and remove one pet without type confusion; unknown data remains an unknown actor. Preserve decoded events and snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Pet.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Elemental.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Slave.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/SlaveManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='companions.pet-detection' AND category_id='companions' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Pet following',description='Pet following status reflects server-observed pet position/status and does not issue movement commands on behalf of an unconfirmed pet state.',acceptance_criteria_json='["Actor movement fixtures must update only the pet record and clear stale following state on removal; keep state snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Pet.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Elemental.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Slave.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/SlaveManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='companions.pet-following' AND category_id='companions' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Pet feeding',description='Feeding is requested only when the pet and a compatible food item are present and the server profile supports the feed exchange; intimacy/status changes require a reply.',acceptance_criteria_json='["An authorized protocol fixture must test accepted/denied feed and reconcile item count/status; missing food or unsupported profile sends no request. Keep redacted trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Pet.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm"]',updated_at=unixepoch() WHERE id='companions.pet-feeding' AND category_id='companions' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Pet capture',description='Capture attempts require an eligible target and supported capture item/skill, and success is recorded only after server-confirmed capture state.',acceptance_criteria_json='["A profile fixture must distinguish accepted, failed, and timed-out capture; failure leaves target/item state unchanged unless server confirms consumption. Preserve sanitized response."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='companions.pet-capture' AND category_id='companions' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Pet evolution',description='Evolution is offered only when server-reported companion level/items/requirements satisfy the selected evolution rule and is finalized from a server response.',acceptance_criteria_json='["A deterministic prerequisite fixture must reject unmet requirements; authorized protocol response must reconcile identity/status changes and failure. Keep requirement matrix and redacted trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Pet.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Elemental.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Slave.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/SlaveManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='companions.pet-evolution' AND category_id='companions' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Homunculi',description='Homunculus identity, stats, skills, and lifecycle events are maintained as a distinct server-owned companion entity.',acceptance_criteria_json='["Golden packet fixtures must update a homunculus without mutating player stats; missing or unknown status remains explicitly unavailable. Preserve packet-to-state assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Slave.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/SlaveManager.pm"]',updated_at=unixepoch() WHERE id='companions.homunculi' AND category_id='companions' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Mercenaries',description='Mercenary records track server-reported lifetime, status, and actions and expire only on server event or confirmed timer semantics.',acceptance_criteria_json='["Clocked protocol fixtures must test lifetime boundary and explicit dismissal; local time alone cannot claim dismissal if server state remains active. Keep event timeline."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Slave.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/SlaveManager.pm"]',updated_at=unixepoch() WHERE id='companions.mercenaries' AND category_id='companions' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Elementals',description='Elemental entities use profile-specific identifiers and status fields, remaining distinct from pets, homunculi, and ordinary actors.',acceptance_criteria_json='["Supported-profile fixtures must decode elemental spawn/status/removal; unknown profile packet must not classify an actor as elemental. Preserve profile matrix."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Elemental.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/SlaveManager.pm"]',updated_at=unixepoch() WHERE id='companions.elementals' AND category_id='companions' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Companion AI',description='Companion commands are selected from supported companion state and configured rules, with actions gated by the companion''s confirmed resources and status.',acceptance_criteria_json='["A deterministic companion-state simulation must choose the specified legal command and stop after dismissal/disconnect; unauthorized or stale actor state yields no action. Keep decision trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Pet.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Elemental.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/Slave.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/SlaveManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm"]',updated_at=unixepoch() WHERE id='companions.companion-ai' AND category_id='companions' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Automatic arrow crafting',description='Arrow crafting selects a configured supported conversion from available materials and weapon/skill state and reconciles the produced quantity from the server response.',acceptance_criteria_json='["A deterministic recipe/inventory fixture must calculate exact material use and expected arrows; insufficient materials or server failure cannot decrement inventory locally. Preserve recipe and response trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm"]',updated_at=unixepoch() WHERE id='crafting.automatic-arrow-crafting' AND category_id='crafting' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Item crafting',description='An item recipe is executable only when its inputs, quantities, and server-supported crafting action are defined; output is accepted from a confirmed response.',acceptance_criteria_json='["Recipe fixtures must assert exact inputs and resulting output on success; missing inputs, unknown recipe, and server rejection remain non-success states. Keep recipe version and inventory diff."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm"]',updated_at=unixepoch() WHERE id='crafting.item-crafting' AND category_id='crafting' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Potion crafting',description='Potion crafting uses only a configured supported formula and sufficient ingredients/skill state, with crafted quantity confirmed by server inventory updates.',acceptance_criteria_json='["A deterministic input fixture must compute the allowed batch and reconcile success/partial/failure; unknown formulas are not inferred. Preserve formula test and response."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm"]',updated_at=unixepoch() WHERE id='crafting.potion-crafting' AND category_id='crafting' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Poison crafting',description='Poison creation validates the required recipe, materials, and skill before transmission and records poison only after server confirmation.',acceptance_criteria_json='["Recipe/skill tests must cover valid and missing prerequisites plus server refusal; resulting inventory must match the server update. Keep fixture and inventory snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm"]',updated_at=unixepoch() WHERE id='crafting.poison-crafting' AND category_id='crafting' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Cooking',description='Cooking actions use a declared recipe, current ingredients, and supported server context; the resulting item/status is based on the server''s response.',acceptance_criteria_json='["A recipe fixture must compute item use and expected output; unsupported recipe, missing inputs, or interruption produces a clear incomplete result. Preserve recipe and sanitized event trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm"]',updated_at=unixepoch() WHERE id='crafting.cooking' AND category_id='crafting' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Production systems',description='A production workflow composes only explicitly registered recipes and server-confirmed steps, and stops when a dependency fails.',acceptance_criteria_json='["A multi-step deterministic fixture must assert input handoff and stop-on-failure, with final inventory reconciled to server responses. Keep workflow trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm"]',updated_at=unixepoch() WHERE id='crafting.production-systems' AND category_id='crafting' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Special item options',description='Special item options are parsed from supported option identifiers and values without assigning semantics to unknown options.',acceptance_criteria_json='["Golden option fixtures must decode known options and preserve unknown raw values; malformed encodings fail the item update without corrupting other inventory. Keep decoder fixtures."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Send.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/Receive.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm"]',updated_at=unixepoch() WHERE id='crafting.special-item-options' AND category_id='crafting' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Configuration reading',description='The configuration reader loads documented key/value settings with their defaults and typed values, reporting the filename and key for malformed or unknown values without silently coercing them.',acceptance_criteria_json='["Fixture tests must parse representative valid settings and reject malformed types/duplicate invalid values; compare the resulting typed settings with expected values. Keep source fixture and diagnostics."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/FileParsers.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/timeouts.txt"]',updated_at=unixepoch() WHERE id='configuration.configuration-reading' AND category_id='configuration' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Table data reading',description='Table readers preserve the declared delimiter, encoding, comment, and column semantics for each supported OpenKore table format.',acceptance_criteria_json='["Golden table fixtures must parse exact rows and handle comments/blank lines; malformed columns or encoding return line-numbered errors without partial table replacement. Preserve fixture hashes and row assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/FileParsers.pm"]',updated_at=unixepoch() WHERE id='configuration.table-data-reading' AND category_id='configuration' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Field data reading',description='Field data parsing validates dimensions and cell encoding and produces the exact walkability grid used by routing.',acceptance_criteria_json='["A miniature field fixture must assert dimensions and selected cells; truncated data, mismatched dimensions, and invalid symbols fail with location context. Keep fixture and parse output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='configuration.field-data-reading' AND category_id='configuration' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Timeout configuration',description='Named timeout settings parse as finite nonnegative durations and are consumed by their corresponding task without confusing seconds and milliseconds.',acceptance_criteria_json='["Boundary tests must parse valid zero/positive values and reject negative, non-finite, and malformed values; task fixtures must expire at the configured duration. Preserve config and fake-clock assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/FileParsers.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/timeouts.txt"]',updated_at=unixepoch() WHERE id='configuration.timeout-configuration' AND category_id='configuration' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Combat parameters',description='Combat settings map each supported target/skill/range parameter to a validated typed rule and preserve explicit defaults.',acceptance_criteria_json='["Representative config fixtures must yield exact decisions for two contrasting combat setups; unknown parameter names or invalid ranges produce diagnostics and do not alter active rules. Keep fixture and decision output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/FileParsers.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/timeouts.txt"]',updated_at=unixepoch() WHERE id='configuration.combat-parameters' AND category_id='configuration' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Navigation parameters',description='Navigation settings such as route, lock map, map-change, and retry options are validated and applied only to the corresponding planner behavior.',acceptance_criteria_json='["Config/field tests must assert one option changes only its documented route rule and invalid coordinate/map values are rejected before movement. Preserve fixture and route result."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/FileParsers.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/timeouts.txt"]',updated_at=unixepoch() WHERE id='configuration.navigation-parameters' AND category_id='configuration' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Item parameters',description='Item filters, protected lists, pickup limits, and weights are parsed into distinct rules used by inventory and loot decisions.',acceptance_criteria_json='["Table-driven item fixtures must prove inclusion, exclusion, and weight behavior; duplicate/conflicting rules follow the documented precedence or fail validation. Keep config and decision matrix."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/FileParsers.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/timeouts.txt"]',updated_at=unixepoch() WHERE id='configuration.item-parameters' AND category_id='configuration' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Skill parameters',description='Skill blocks parse skill identity, target, level, timing, and condition fields into a validated rule without dropping unsupported fields silently.',acceptance_criteria_json='["Compatibility fixtures must map each supported field to the expected cast decision and report unsupported/malformed fields by name; no request is emitted on parse error. Preserve source-format fixtures."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/FileParsers.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/timeouts.txt"]',updated_at=unixepoch() WHERE id='configuration.skill-parameters' AND category_id='configuration' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Conditional blocks',description='A conditional block associates its predicate with the intended setting/action and evaluates it from one consistent runtime snapshot.',acceptance_criteria_json='["Parser/evaluator tests must prove true and false branches and reject malformed nesting, unknown identifiers, and missing values before side effects. Keep fixture and decision output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm"]',updated_at=unixepoch() WHERE id='configuration.conditional-blocks' AND category_id='configuration' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Dynamic configuration changes',description='Runtime changes become visible at a defined task boundary and cannot leave one decision using a mixture of old and new dependent values.',acceptance_criteria_json='["A controlled task test must change a setting during a queued action and assert the documented snapshot boundary; invalid update leaves the old snapshot active. Preserve state diff."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/FileParsers.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/timeouts.txt"]',updated_at=unixepoch() WHERE id='configuration.dynamic-configuration-changes' AND category_id='configuration' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Configuration reload',description='Reload parses a complete new configuration before replacing active settings; a failed reload retains the last known-good configuration.',acceptance_criteria_json='["Fixture tests must assert successful atomic replacement and malformed-file rollback, including no partially applied values. Keep before/after snapshots and parser errors."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/FileParsers.pm"]',updated_at=unixepoch() WHERE id='configuration.configuration-reload' AND category_id='configuration' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Configuration persistence',description='Persisted changes are written in the compatible format with stable keys and are read back to the same typed values on restart.',acceptance_criteria_json='["Round-trip tests must preserve comments/unsupported entries according to policy and reproduce values; failed write leaves prior file intact and reports the path. Preserve fixture and round-trip diff."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/FileParsers.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/timeouts.txt"]',updated_at=unixepoch() WHERE id='configuration.configuration-persistence' AND category_id='configuration' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Advanced formats',description='Advanced supported configuration constructs retain their documented quoting, escaping, multiline, and include semantics without executing arbitrary content.',acceptance_criteria_json='["Golden fixtures must test supported constructs and reject unsafe/unsupported syntax with file/line diagnostics; include cycles are bounded. Keep fixtures and parser output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/FileParsers.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/timeouts.txt"]',updated_at=unixepoch() WHERE id='configuration.advanced-formats' AND category_id='configuration' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Extension configuration',description='Extension settings are namespaced to the owning extension and validated against its declared options before plugin initialization.',acceptance_criteria_json='["Two plugin config fixtures must remain isolated; unknown plugin or invalid option prevents that extension from starting without corrupting core configuration. Preserve init result and diagnostics."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Plugins.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm"]',updated_at=unixepoch() WHERE id='configuration.extension-configuration' AND category_id='configuration' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Aliases',description='Command aliases expand only at command boundaries using the configured arguments and do not recursively rewrite quoted text or unrelated message content.',acceptance_criteria_json='["Parser tests must assert exact expansion, argument preservation, and cycle rejection; unmatched input is passed through unchanged. Keep alias fixtures."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/control/config.txt","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='configuration.aliases' AND category_id='configuration' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Profiles',description='A named profile provides an isolated overlay with explicit precedence over shared configuration and can be switched without stale values leaking between profiles.',acceptance_criteria_json='["Round-trip tests across two profiles must assert only declared overrides differ and returning restores original effective settings; invalid profile preserves active config. Keep snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/profiles/profiles.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Settings.pm"]',updated_at=unixepoch() WHERE id='configuration.profiles' AND category_id='configuration' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Macro',description='Macro files parse supported triggers, delays, labels, and commands into a bounded execution plan; malformed blocks do not run partial commands.',acceptance_criteria_json='["Parser and fake-clock fixtures must execute a declared macro in exact order and cancel it on malformed syntax, timeout, or stop; preserve macro file and action trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/macro/macro.pl"]',updated_at=unixepoch() WHERE id='scripting.macro' AND category_id='scripting' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Composite commands',description='A composite command expands into registered commands with their arguments and stops at the first failed prerequisite or explicit cancellation.',acceptance_criteria_json='["A command-sequence fixture must assert exact command order and propagation; unknown command and invalid arguments produce diagnostics without running later steps. Keep parsed plan and trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/macro/macro.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/eventMacro/eventMacro.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Plugins.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='scripting.composite-commands' AND category_id='scripting' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Declarative automations',description='Declarative routines validate their trigger, conditions, and action references before execution and run only from a current event snapshot.',acceptance_criteria_json='["Schema/evaluator fixtures must accept a valid routine and reject unknown actions/fields; simulation must show false conditions emit no action and failure terminates dependents. Preserve routine fixture and result."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/macro/macro.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/eventMacro/eventMacro.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Plugins.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='scripting.declarative-automations' AND category_id='scripting' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='EventMacro',description='EventMacro triggers only on matching supported events and evaluates its declared conditions before scheduling commands.',acceptance_criteria_json='["A synthetic event stream must trigger exactly matching blocks once and ignore unrelated/duplicate events; malformed block and cancelled task produce no delayed command. Keep event trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/eventMacro/eventMacro.pl"]',updated_at=unixepoch() WHERE id='scripting.eventmacro' AND category_id='scripting' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Conditions',description='Script conditions parse into a bounded expression tree and evaluate deterministically against typed values; unknown functions or incompatible operands fail explicitly.',acceptance_criteria_json='["Table-driven parser/evaluator tests must assert true/false/error for supported comparisons and reject unsupported operators without executing actions. Preserve expression fixtures."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/macro/macro.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/eventMacro/eventMacro.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Plugins.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='scripting.conditions' AND category_id='scripting' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Variables',description='Script variables have declared scope and lifetime, retain typed values across the specified blocks, and do not leak between independent sessions.',acceptance_criteria_json='["A multi-script test must assert local/global lifetime and session isolation; undefined or incompatible assignment returns a diagnostic rather than a fabricated value. Keep state snapshots."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/macro/macro.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/eventMacro/eventMacro.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Plugins.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='scripting.variables' AND category_id='scripting' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Functions',description='Callable script functions validate argument count/types and return a defined result or error to the caller.',acceptance_criteria_json='["Function fixtures must assert successful return, wrong-argument errors, and nested failure propagation; recursion/step limits stop runaway execution. Preserve test program and trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/macro/macro.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/eventMacro/eventMacro.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Plugins.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='scripting.functions' AND category_id='scripting' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Hooks',description='Extension hooks run only for registered event names and in documented order, and one failing hook cannot corrupt core event dispatch.',acceptance_criteria_json='["Plugin fixtures must assert registration/order and isolated failure handling; unregistering a plugin prevents later callbacks. Keep hook trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Plugins.pm"]',updated_at=unixepoch() WHERE id='scripting.hooks' AND category_id='scripting' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Extension API',description='The extension API exposes documented typed events and commands with lifecycle-scoped registration and explicit errors for unsupported operations.',acceptance_criteria_json='["A minimal test extension must register, receive one event, unregister, and fail predictably on an unsupported call; preserve API fixture and lifecycle output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/macro/macro.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/plugins/eventMacro/eventMacro.pl","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Plugins.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm"]',updated_at=unixepoch() WHERE id='scripting.extension-api' AND category_id='scripting' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='CLI',description='The CLI starts with the selected configuration, reports initialization errors, and returns a nonzero process status when startup cannot establish required state.',acceptance_criteria_json='["Command-line integration tests must verify valid startup and missing/invalid config exit behavior, including stable machine-readable status where defined. Keep captured output and exit assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.cli' AND category_id='ui' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Help',description='Help output lists each supported command with its accepted arguments and identifies unknown commands without executing them.',acceptance_criteria_json='["Snapshot tests must compare representative help entries to the registered command table and ensure unknown command input returns help/error only. Preserve snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.help' AND category_id='ui' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Basic commands',description='Basic control commands parse their documented arguments and return a clear success or usage error without sending unrelated protocol actions.',acceptance_criteria_json='["Table-driven command tests must exercise one valid form and invalid/missing arguments for each exposed basic command; keep command registry and result snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.basic-commands' AND category_id='ui' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Character status view',description='The status view renders only the current server-confirmed character values and labels unknown fields as unavailable.',acceptance_criteria_json='["Given a fixed character-state snapshot, output must contain exact HP/SP/level/position and omit stale values after disconnect; preserve expected text snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm"]',updated_at=unixepoch() WHERE id='ui.character-status-view' AND category_id='ui' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Actor lists',description='Actor lists distinguish actor types, show stable identities, and remove entities only when current state says they disappeared.',acceptance_criteria_json='["A fixed world snapshot must render each entity once with correct type and no removed/stale actor; keep snapshot fixture and output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ActorList.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm"]',updated_at=unixepoch() WHERE id='ui.actor-lists' AND category_id='ui' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Inventory view',description='Inventory output shows current item counts, equipment slots, and unknown metadata without inventing item names or quantities.',acceptance_criteria_json='["A deterministic inventory fixture must match expected rows and update after a server delta; malformed item state produces a visible unavailable/error marker. Preserve output snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/InventoryList/Inventory.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm"]',updated_at=unixepoch() WHERE id='ui.inventory-view' AND category_id='ui' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Logs',description='Logs include event time, severity, and relevant task/session context while redacting credentials, one-time codes, and sensitive message payloads.',acceptance_criteria_json='["A logger test must format representative events and scan output for known secret markers; severity filtering must include/exclude the expected events. Keep sanitized output fixture."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.logs' AND category_id='ui' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Control commands',description='Control commands pause, resume, stop, or change mode through the shared scheduler and report the resulting state transition.',acceptance_criteria_json='["Command-state tests must prove each allowed transition and reject commands not valid in the current state; stopping prevents later queued actions. Preserve command and event trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.control-commands' AND category_id='ui' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Experience reports',description='Experience reports derive rates and deltas from timestamped server-confirmed experience samples and show insufficient-data state instead of a fabricated rate.',acceptance_criteria_json='["Fixed samples with known intervals must yield exact deltas/rate; duplicate timestamps, level reset, and empty history must be handled explicitly. Keep input and report snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Actor/You.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm"]',updated_at=unixepoch() WHERE id='ui.experience-reports' AND category_id='ui' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Damage reports',description='Damage reports aggregate decoded damage events by the declared source/target and exclude duplicate or unconfirmed events.',acceptance_criteria_json='["A fixture with known event IDs and amounts must yield exact totals and ignore duplicates; missing attribution is grouped as unknown, not assigned arbitrarily. Preserve event fixture and output."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.damage-reports' AND category_id='ui' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Item reports',description='Item reports distinguish acquired, consumed, sold, stored, and unknown deltas based on authoritative inventory/transaction events.',acceptance_criteria_json='["A transaction stream must reconcile exact per-category counts; an unexplained inventory difference remains unknown rather than counted as loot. Keep stream and report assertions."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.item-reports' AND category_id='ui' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Statistics',description='Session statistics use documented event counters and reset boundaries, distinguishing current session from persisted totals.',acceptance_criteria_json='["A deterministic event sequence must yield exact counters before and after reset/disconnect; repeated events follow idempotency rules. Preserve counter snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.statistics' AND category_id='ui' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Interactive configuration',description='Interactive configuration displays the current typed value, validates user input before applying it, and reports write/reload errors without losing the previous value.',acceptance_criteria_json='["CLI tests must cover valid change, invalid range, cancel, and persistence failure; active setting remains unchanged on failure. Keep input/output capture."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.interactive-configuration' AND category_id='ui' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Graphical interface',description='The optional GUI, if enabled for the milestone, exposes session controls and status through the same public state/actions as the CLI and does not own protocol state.',acceptance_criteria_json='["A headless UI contract test must verify controls invoke shared commands and status updates from fixture events; no GUI availability is reported until an actual supported implementation passes. Keep platform test evidence."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Wx.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Win32.pm"]',updated_at=unixepoch() WHERE id='ui.graphical-interface' AND category_id='ui' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Visual map',description='The map view plots actors and the local character at server-confirmed coordinates in the active field and marks unknown/out-of-bounds positions distinctly.',acceptance_criteria_json='["A field/world fixture must render exact entity coordinates and clear the map on field change; missing field or invalid location must not place actors at an arbitrary cell. Preserve render snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.visual-map' AND category_id='ui' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Route view',description='The route view displays the current planned path separately from confirmed position and updates when a route is replanned or cancelled.',acceptance_criteria_json='["A deterministic navigation state fixture must show the route endpoints and confirmed location separately; cancellation removes the stale path. Keep visual or text snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.route-view' AND category_id='ui' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Equipment view',description='Equipment view maps confirmed equipped item IDs to slots and distinguishes pending changes from server-confirmed changes.',acceptance_criteria_json='["A fixed equipment state must render slot/item pairs and pending markers; a rejected equip restores the confirmed display. Preserve snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.equipment-view' AND category_id='ui' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Skills view',description='Skills view lists learned levels and current cooldown/availability from server state and distinguishes unavailable metadata.',acceptance_criteria_json='["A skill fixture must render exact learned skills and cooldown boundary; unknown IDs remain labeled unknown without guessed descriptions. Keep snapshot."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.skills-view' AND category_id='ui' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Dialogue view',description='Dialogue view presents the current server prompt and valid choices, disabling stale choices after the prompt changes or closes.',acceptance_criteria_json='["Protocol UI fixtures must update choices on each prompt and reject clicks against stale prompt IDs; preserve interaction trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.dialogue-view' AND category_id='ui' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Session management',description='Session controls display independent connection stages and allow stopping a session without leaving pending tasks or stale identity visible.',acceptance_criteria_json='["State-machine UI tests must cover connect, in-game, disconnect, and stop; stopped session clears identity and cancels work. Keep output snapshot and task trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface/Console.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Commands.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Interface.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Log.pm"]',updated_at=unixepoch() WHERE id='ui.session-management' AND category_id='ui' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Architecture',description='The Rust workspace separates protocol I/O, parsing, world state, decisions, and user interfaces behind explicit contracts, with no dependency cycle between those layers.',acceptance_criteria_json='["Architecture tests must compile each crate boundary and prove core state/decision modules run without network, UI, or filesystem adapters; preserve dependency graph and test output."]',upstream_references_json='[]',updated_at=unixepoch() WHERE id='reliability.architecture' AND category_id='reliability' AND milestone_id='foundation' AND is_required=1;

UPDATE roadmap_features SET title='Licensing',description='Every distributed RustKore component, dependency, and bundled data file has a reviewed license and attribution record compatible with the chosen project license.',acceptance_criteria_json='["A license audit artifact must enumerate direct/transitive dependencies and data sources and identify exceptions; release packaging is blocked by any unresolved incompatible or undocumented license. Keep generated report."]',upstream_references_json='[]',updated_at=unixepoch() WHERE id='reliability.licensing' AND category_id='reliability' AND milestone_id='foundation' AND is_required=1;

UPDATE roadmap_features SET title='Benchmark strategy',description='Benchmarks define reproducible workloads, correctness checks, toolchain/profile, hardware, warmup, and measurement units before performance claims are published.',acceptance_criteria_json='["A benchmark protocol fixture must reproduce a baseline and verify correctness assertions; missing environment metadata makes results ineligible for comparison. Preserve command and metadata."]',upstream_references_json='[]',updated_at=unixepoch() WHERE id='reliability.benchmark-strategy' AND category_id='reliability' AND milestone_id='foundation' AND is_required=1;

UPDATE roadmap_features SET title='Test infrastructure',description='The test harness runs pure unit tests and deterministic protocol/field fixtures without requiring an external game server or credentials.',acceptance_criteria_json='["CI must execute representative parser, routing, state, and scheduler fixtures offline and fail on an intentionally mismatched expected result; retain command output."]',upstream_references_json='["https://github.com/OpenKore/openkore/tree/a440c7fc842767f7e413b258f63acbd34425b000/src/test","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/Benchmark.pm"]',updated_at=unixepoch() WHERE id='reliability.test-infrastructure' AND category_id='reliability' AND milestone_id='foundation' AND is_required=1;

UPDATE roadmap_features SET title='Rust workspace',description='The repository builds as a minimal Rust workspace with declared members and shared dependency policy, and an empty member can be tested independently.',acceptance_criteria_json='["Run workspace metadata and package tests in a clean checkout; undeclared paths or an invalid member must fail before application tests. Preserve Cargo metadata output."]',upstream_references_json='[]',updated_at=unixepoch() WHERE id='reliability.rust-workspace' AND category_id='reliability' AND milestone_id='foundation' AND is_required=1;

UPDATE roadmap_features SET title='CI',description='Continuous integration runs formatting, lint, and test checks on the declared supported toolchain and reports a failing check against the commit that introduced it.',acceptance_criteria_json='["A workflow validation must show all required jobs run on a sample pull request and fail when a controlled check fails; keep workflow run evidence."]',upstream_references_json='[]',updated_at=unixepoch() WHERE id='reliability.ci' AND category_id='reliability' AND milestone_id='foundation' AND is_required=1;

UPDATE roadmap_features SET title='Deterministic state',description='Given the same ordered input events and configuration, the state reducer produces the same world/session state without reading wall-clock or randomness implicitly.',acceptance_criteria_json='["Replay a fixed event log twice with injected clock/random source and compare canonical state hashes; different seeds/clocks must be explicit inputs. Preserve event log and hashes."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Globals.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ActorList.pm"]',updated_at=unixepoch() WHERE id='reliability.deterministic-state' AND category_id='reliability' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Data validation',description='External config, table, field, packet, and CLI data are validated at boundaries with field-specific errors before entering core state.',acceptance_criteria_json='["Malformed fixtures for each boundary must be rejected with location/context and leave the last valid state intact; retain validation matrix."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/FileParsers.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Field.pm"]',updated_at=unixepoch() WHERE id='reliability.data-validation' AND category_id='reliability' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Error handling',description='Errors carry operation and recovery classification through public boundaries, and callers can distinguish retryable, user-correctable, and fatal failures.',acceptance_criteria_json='["Injected failures across parser, transport, task, and storage adapters must map to the expected error class and stop/retry policy; preserve test matrix."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ErrorHandler.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/Exceptions.pm"]',updated_at=unixepoch() WHERE id='reliability.error-handling' AND category_id='reliability' AND milestone_id='prototype' AND is_required=1;

UPDATE roadmap_features SET title='Session stability',description='A session maintains valid transitions under packet bursts, timeouts, disconnects, and reconnects without duplicated identity or leaked active tasks.',acceptance_criteria_json='["Stress a deterministic session event stream with reconnect boundaries and assert invariants after every event; retain state and resource counters."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm"]',updated_at=unixepoch() WHERE id='reliability.session-stability' AND category_id='reliability' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Memory behavior',description='Actor, event, and log collections have explicit lifecycle bounds or removal rules so stale entities and diagnostics do not grow indefinitely.',acceptance_criteria_json='["A long deterministic spawn/remove/log workload must keep retained item counts within declared limits while preserving live entries; record memory/count measurements."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/ObjectList.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ActorList.pm"]',updated_at=unixepoch() WHERE id='reliability.memory-behavior' AND category_id='reliability' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Latency behavior',description='Latency measurements identify queue, network, parsing, and decision stages separately and do not count unconfirmed requests as completed actions.',acceptance_criteria_json='["A scripted workload must emit stage timestamps and verify duration calculations against injected clock; preserve raw sample metadata and report."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/Benchmark.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm"]',updated_at=unixepoch() WHERE id='reliability.latency-behavior' AND category_id='reliability' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Recovery',description='Recoverable faults return the client to a known state and require fresh confirmation before resuming actions; fatal faults stop automation and retain an actionable diagnostic.',acceptance_criteria_json='["Fault-injection tests at connect, parse, movement, and task stages must assert cleanup and no stale action after recovery; preserve error and transition trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/ErrorHandler.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm"]',updated_at=unixepoch() WHERE id='reliability.recovery' AND category_id='reliability' AND milestone_id='alpha' AND is_required=1;

UPDATE roadmap_features SET title='Long-running automation',description='Long-running routines periodically reconcile server state and release completed/expired task resources rather than accumulating duplicate work.',acceptance_criteria_json='["A simulated multi-hour clock/event test must keep task/resource counts bounded and reconcile status after periodic updates; interruption stops timers. Preserve counters and trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm"]',updated_at=unixepoch() WHERE id='reliability.long-running-automation' AND category_id='reliability' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Routine coordination',description='Combat, navigation, storage, and commerce routines acquire/release declared action ownership and cannot issue conflicting movement or interaction commands concurrently.',acceptance_criteria_json='["A deterministic competing-task schedule must prove one owner per exclusive resource and release on success/error/cancel; keep scheduler trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/TaskManager.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/AI/CoreLogic.pm"]',updated_at=unixepoch() WHERE id='reliability.routine-coordination' AND category_id='reliability' AND milestone_id='beta' AND is_required=1;

UPDATE roadmap_features SET title='Cross-platform tests',description='The same deterministic core fixtures pass on supported stable Rust targets for Windows, Linux, and macOS, with platform-specific adapters isolated.',acceptance_criteria_json='["CI matrix evidence must report target/toolchain and test results for each declared OS; a skipped platform job is not counted as passing. Preserve workflow results."]',upstream_references_json='["https://github.com/OpenKore/openkore/tree/a440c7fc842767f7e413b258f63acbd34425b000/.github/workflows","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/Makefile"]',updated_at=unixepoch() WHERE id='reliability.cross-platform-tests' AND category_id='reliability' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Multiple sessions',description='Independent sessions maintain separate sockets, characters, state, timers, and task queues without cross-session event leakage.',acceptance_criteria_json='["A two-session simulation must interleave identical actor IDs and prove each snapshot remains isolated; closing one session leaves the other active. Keep two-session trace."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Network/DirectConnection.pm","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Globals.pm"]',updated_at=unixepoch() WHERE id='reliability.multiple-sessions' AND category_id='reliability' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Comparative regressions',description='Correctness/performance baselines are compared only for equivalent workload, toolchain, and environment, with regressions tied to measured data rather than a subjective estimate.',acceptance_criteria_json='["A paired benchmark run must verify workload hash and environment match and report raw samples plus threshold; unmatched runs are rejected. Preserve baseline and comparison output."]',upstream_references_json='["https://github.com/OpenKore/openkore/tree/a440c7fc842767f7e413b258f63acbd34425b000/src/test","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/src/Utils/Benchmark.pm"]',updated_at=unixepoch() WHERE id='reliability.comparative-regressions' AND category_id='reliability' AND milestone_id='rc' AND is_required=1;

UPDATE roadmap_features SET title='Documentation',description='Stable-scope documentation lists supported platforms, configuration formats, known limitations, and reproducible install/run/test steps that match the release artifact.',acceptance_criteria_json='["A clean-environment walkthrough must complete install, config validation, fixture test, and documented limitation checks; preserve command transcript and release docs."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/README.md","https://github.com/OpenKore/openkore/tree/a440c7fc842767f7e413b258f63acbd34425b000/src/doc"]',updated_at=unixepoch() WHERE id='reliability.documentation' AND category_id='reliability' AND milestone_id='stable' AND is_required=1;

UPDATE roadmap_features SET title='Distribution',description='Release archives include the executable, required notices, and supported runtime assets for each declared target and exclude secrets or development-only files.',acceptance_criteria_json='["Build/package tests must inspect archive contents and run a smoke command on each target; missing notice/asset or included credential fixture fails packaging. Keep artifact manifest and checksums."]',upstream_references_json='["https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/Makefile","https://github.com/OpenKore/openkore/blob/a440c7fc842767f7e413b258f63acbd34425b000/makedist.sh"]',updated_at=unixepoch() WHERE id='reliability.distribution' AND category_id='reliability' AND milestone_id='stable' AND is_required=1;

UPDATE roadmap_features SET title='Stable scope validation',description='A stable release is allowed only when every accumulated mandatory roadmap requirement is verified with current evidence and optional requirements are excluded from the gate.',acceptance_criteria_json='["A release-gate test must calculate cumulative mandatory requirements from the catalog and block one missing verification; preserve gate input and output."]',upstream_references_json='[]',updated_at=unixepoch() WHERE id='reliability.stable-scope-validation' AND category_id='reliability' AND milestone_id='stable' AND is_required=1;

UPDATE roadmap_features SET title='Proven performance',description='Performance claims use reproducible benchmark evidence against a named baseline and report workload, compiler, hardware, latency, memory, and uncertainty.',acceptance_criteria_json='["A release benchmark report must contain raw samples and correctness checks for each claim; absent comparable baseline or metadata prevents a claim. Keep benchmark artifact."]',upstream_references_json='[]',updated_at=unixepoch() WHERE id='reliability.proven-performance' AND category_id='reliability' AND milestone_id='stable' AND is_required=1;

