INSERT INTO roadmap_change_history (id,feature_id,actor_id,action,details_json,created_at,scenario) VALUES ('roadmap-catalog-1-0-1',NULL,NULL,'catalog.migration_applied',json_object('catalogVersion','1.0.1','catalogHash','b5af2a2dbc8134957e68fdc1b73a34a6edf4b80049d2716dbf7048a24b902683','featureCount',278),unixepoch(),'actual');
